  `id` int(11) NOT NULL COMMENT 'chỉ dùng dòng id nhỏ nhất (1)',
  `rod_item` int(11) NOT NULL DEFAULT 164 COMMENT 'item_template.id cần câu — phải cầm ở ô vũ khí',
  `bait_item` int(11) NOT NULL DEFAULT 152 COMMENT 'item_template.id mồi câu — tốn 1 mỗi lần quăng cần (câu được / hụt / sổng đều mất)',
  `loot` mediumtext NOT NULL COMMENT 'JSON [{"i":251,"w":20}] — món = RewardItem (i q l s d) + w tỉ lệ %; l bỏ trống = KHOÁ; tổng w < 100 thì phần còn lại = cá sổng, > 100 thì chia theo tỉ lệ'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='câu cá (op 57) — server nạp lại mỗi phút';

