--
-- Cấu trúc bảng cho bảng `giftcode`
--

CREATE TABLE `giftcode` (
  `code` varchar(32) NOT NULL COMMENT 'mã, nhập không phân biệt hoa thường',
  `name` varchar(128) NOT NULL COMMENT 'mô tả hiện ở Danh sách Giftcode',
  `enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '0 = tắt mã',
  `listed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '1 = hiện ở khung Danh sách Giftcode',
  `start_at` datetime DEFAULT NULL COMMENT 'NULL = dùng ngay',
  `end_at` datetime DEFAULT NULL COMMENT 'NULL = không hết hạn',
  `min_level` int(11) NOT NULL DEFAULT 0,
  `max_level` int(11) NOT NULL DEFAULT 0 COMMENT '0 = không giới hạn',
  `class_ids` varchar(64) DEFAULT NULL COMMENT 'CSV loại vũ khí được nhập: 1 Chưa vũ khí, 2 Rìu, 3 Cung, 4 Ná, 5 Giáo, 6 Roi; NULL = tất cả',
  `genders` varchar(16) DEFAULT NULL COMMENT 'CSV nhân vật được nhập: 1 Rinn, 2 Lyria, 3 Bruk; NULL = tất cả',
  `player_names` text DEFAULT NULL COMMENT 'CSV tên nhân vật được nhập; NULL = ai cũng được',
  `max_uses` int(11) NOT NULL DEFAULT 0 COMMENT 'tổng lượt nhập cả server, 0 = không giới hạn',
  `uses_per_player` int(11) NOT NULL DEFAULT 1 COMMENT 'số lần mỗi nhân vật được nhập',
  `rewards` text DEFAULT NULL COMMENT 'JSON [{"i":38,"q":1,"l":1,"s":[[9,100]],"d":3,"c":0,"g":1}] — c = chỉ loại vũ khí này nhận, g = chỉ nhân vật này nhận (0 = ai cũng nhận); không ghi l thì KHOÁ'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='giftcode (op 33 sub 1) — server nạp lại mỗi phút';

