--
-- Cấu trúc bảng cho bảng `map_template`
--

CREATE TABLE `map_template` (
  `id` int(11) NOT NULL,
  `name` varchar(128) NOT NULL,
  `music` varchar(64) NOT NULL DEFAULT '' COMMENT 'tên nhạc nền (AudioManager.playMusic)',
  `tile_cols` int(11) NOT NULL COMMENT 'số cột tile',
  `tile_rows` int(11) NOT NULL COMMENT 'số hàng tile',
  `tile_size` int(11) NOT NULL DEFAULT 72,
  `width` int(11) NOT NULL COMMENT 'pixel = tile_cols * tile_size',
  `height` int(11) NOT NULL COMMENT 'pixel = tile_rows * tile_size',
  `spawn_x` float NOT NULL COMMENT 'điểm xuất hiện mặc định (nhân vật mới / dịch chuyển không rõ cửa)',
  `spawn_y` float NOT NULL,
  `max_players_per_zone` int(11) NOT NULL DEFAULT 30 COMMENT 'mỗi khu tối đa bấy nhiêu người',
  `zone_count` int(11) NOT NULL DEFAULT 1 COMMENT 'số khu mở sẵn (khu 0..n-1, luôn tồn tại); đầy hết thì tự mở thêm khu',
  `waypoints` mediumtext NOT NULL DEFAULT '[]' COMMENT 'JSON [{name,x,y,w,h,targetMapId?,targetX?,targetY?,interact?}] - interact true = cửa phải bấm, false = chạm là qua',
  `objects` mediumtext NOT NULL DEFAULT '[]' COMMENT 'JSON [{layer,kind?,sprite,x,y,w?,h?,parallaxX?,parallaxY?,flipX?,flipY?,tiledX?,tiledY?,scale?,followCamera?}] - thứ tự = thứ tự vẽ',
  `colliders` mediumtext NOT NULL DEFAULT '[]' COMMENT 'JSON [[x,y,w,h],[x,y,w,h,1]...] - nền/tường va chạm (pixel, gốc dưới-trái), phần tử thứ 5 = 1: nền 1 chiều (nhảy xuyên từ dưới lên)',
  `npcs` mediumtext NOT NULL DEFAULT '[]' COMMENT 'JSON [{id,x,y,flipX?}] - NPC dat tren map (npc_template.id)',
  `mobs` mediumtext NOT NULL DEFAULT '[]' COMMENT 'JSON [{id,variant?,x,y,count?,range?,respawn?}] - diem sinh quai (mob_template.id)',
  `plants` mediumtext NOT NULL DEFAULT '[]' COMMENT 'JSON [{id,x,y,respawn?}] - cây / hoa thu hoạch (plant_template.id), sửa bằng TLNT-Editor',
  `waters` mediumtext NOT NULL DEFAULT '[]' COMMENT 'JSON [{x,y,w,h,fish?}] - vung nuoc cau ca (dinh hop = mat nuoc)'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

