  `tabs` mediumtext NOT NULL COMMENT 'JSON [{"name":"Tạp hóa","icon":"icon/281","items":[{"i":239,"q":1,"p":5000,"cur":0,"l":0,"s":[[3,300]],"d":0}]}] — p giá / lần mua, cur 0 vàng / 1 vàng khoá (thiếu bù vàng) / 2 lam thạch; l bỏ trống = khoá nếu mua bằng vàng khoá'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='cửa hàng NPC (op 55) — TLNT-Editor sửa, server nạp lại mỗi phút';

