--
-- Cấu trúc bảng cho bảng `skill_effect`
--

CREATE TABLE `skill_effect` (
  `skill_id` int(11) NOT NULL COMMENT 'skill_template.id',
  `level` int(11) NOT NULL COMMENT 'skill_level.level',
  `damage_percent` int(11) DEFAULT NULL COMMENT '% Tấn công mỗi đòn',
  `hits` tinyint(4) NOT NULL DEFAULT 1 COMMENT 'số đòn gộp trong 1 gói',
  `aoe_targets` tinyint(4) DEFAULT NULL COMMENT 'số mục tiêu phụ',
  `aoe_percent` int(11) DEFAULT NULL COMMENT '% sát thương đòn chính lên mỗi mục tiêu phụ',
  `armor_pen` int(11) DEFAULT NULL,
  `accuracy` int(11) DEFAULT NULL,
  `crit_damage_percent` int(11) DEFAULT NULL,
  `lifesteal_percent` int(11) DEFAULT NULL,
  `bleed_percent` int(11) DEFAULT NULL COMMENT '% Tấn công mỗi nhịp chảy máu',
  `bonus_percent` int(11) DEFAULT NULL COMMENT 'sát thương cộng thêm = % bonus_stat',
  `bonus_stat` varchar(16) DEFAULT NULL COMMENT 'hp | mp | accuracy | crit | evasion',
  `status` varchar(16) DEFAULT NULL COMMENT 'ice | weaken | lightning | stun | root',
  `status_power` int(11) DEFAULT NULL,
  `status_ms` int(11) DEFAULT NULL,
  `heal_percent` int(11) DEFAULT NULL COMMENT '% HP tối đa',
  `damage_reduction_percent` int(11) DEFAULT NULL,
  `reflect_percent` int(11) DEFAULT NULL,
  `attack_speed_percent` int(11) DEFAULT NULL,
  `move_speed_percent` int(11) DEFAULT NULL,
  `illusion_percent` int(11) DEFAULT NULL,
  `duration_ms` int(11) DEFAULT NULL COMMENT 'thời gian buff'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

