(56, 'level', 30, 'Đạt cấp độ 30', 'Không ngừng rèn luyện qua từng trận chiến để tích lũy kinh nghiệm và vươn tới sức mạnh cao hơn. Cày, cày nữa, cày mãi...!', 1, '[{\"i\":274,\"q\":5000,\"l\":1},{\"i\":145,\"q\":250,\"l\":1}]', 56),
(57, 'level', 45, 'Đạt cấp độ 45', 'Không ngừng rèn luyện qua từng trận chiến để tích lũy kinh nghiệm và vươn tới sức mạnh cao hơn. Cày, cày nữa, cày mãi...!', 1, '[{\"i\":274,\"q\":10000,\"l\":1},{\"i\":145,\"q\":500,\"l\":1}]', 57),
(58, 'level', 60, 'Đạt cấp độ 60', 'Không ngừng rèn luyện qua từng trận chiến để tích lũy kinh nghiệm và vươn tới sức mạnh cao hơn. Cày, cày nữa, cày mãi...!', 1, '[{\"i\":274,\"q\":15000,\"l\":1},{\"i\":145,\"q\":1000,\"l\":1}]', 58),
(59, 'level', 75, 'Đạt cấp độ 75', 'Không ngừng rèn luyện qua từng trận chiến để tích lũy kinh nghiệm và vươn tới sức mạnh cao hơn. Cày, cày nữa, cày mãi...!', 1, '[{\"i\":274,\"q\":20000,\"l\":1},{\"i\":145,\"q\":1500,\"l\":1}]', 59),
(60, 'level', 100, 'Đạt cấp độ 100', 'Không ngừng rèn luyện qua từng trận chiến để tích lũy kinh nghiệm và vươn tới sức mạnh cao hơn. Cày, cày nữa, cày mãi...!', 1, '[{\"i\":274,\"q\":25000,\"l\":1},{\"i\":145,\"q\":2000,\"l\":1}]', 60);
