INSERT INTO `char_template` (`id`, `name`, `skeleton_path`, `avatar_icon_path`, `info_table_json`, `stat_ratings`, `selectable`) VALUES
(1, 'Rinn', 'skeletons/chars/2', 'ui/159', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"Rinn là con trai của thủ lĩnh Gorun – vị thủ lĩnh từng dẫn dắt bộ tộc chống lại Khế Ước Hiến Tế với Tinh Linh Bầu Trời. hiện tại cậu là người kế thừa và thống lĩnh bộ lạc Eldarah\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"[#FFF600]Nội tại:\\n+5% Khuếch đại tấn công\\n+10% MP\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"Vũ khí khuyên dùng\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"padTop\":50,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/598\"},\"cell\":{\"size\":[340,173],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/599\"},\"cell\":{\"size\":[340,173],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":24,\"text\":\"Roi da\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":24,\"text\":\"Ná thun\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"Rinn sở hữu thể lực rất tốt và lối chiến đấu linh hoạt, cho phép cậu duy trì phong độ ổn định trong những trận chiến kéo dài. Tương tác tốt với lối xây dựng trang bị tăng MP và Né tránh không phụ thuộc vào sức mạnh bộc phát\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"padBottom\":50,\"spaceTop\":20,\"row\":true,\"growX\":true}}]}', '[0.6,0.5,0.7,0.4]', 1),
(2, 'Lyria', 'skeletons/chars/1', 'ui/160', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"Lyria là nữ thợ săn của bộ tộc Sayari, lớn lên giữa khu rừng, là một trong số ít người sống sót sau biến cố Hắc Linh thức tỉnh tại Sayari mang theo ký ức kinh hoàng về đêm Cội Rễ Nứt Vỡ\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"[#FFF600]Nội tại:\\n+5% Tấn công\\n+5% Sát thương chí mạng\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"Vũ khí khuyên dùng\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"padTop\":50,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/595\"},\"cell\":{\"size\":[340,173],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/596\"},\"cell\":{\"size\":[340,173],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":24,\"text\":\"Cung tên\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":24,\"text\":\"Giáo\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"Lyria có thể lực và khả năng hồi phục khá yếu, nhưng lại sở hữu thân thủ nhanh nhẹn cùng kỹ năng săn mồi đáng sợ. Cô có thể tung ra những đòn chí mạng kết liễu mục tiêu trong khoảnh khắc. Tương tác tốt với lối xây dựng trang bị tăng Tấn công, Chí mạng và dồn sát thương chớp nhoáng\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"padBottom\":50,\"spaceTop\":20,\"row\":true,\"growX\":true}}]}', '[1.0,0.3,0.3,0.2]', 1),
(3, 'Bruk', 'skeletons/chars/3', 'ui/161', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"Bruk là chiến binh của cao nguyên Darguun, lớn lên giữa những vách đá hiểm trở và gió lạnh khắc nghiệt. Cuộc sống sinh tồn nơi đây đã rèn luyện cậu với sức mạnh thể chất vượt trội\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"[#FFF600]Nội tại:\\n+5% Giáp\\n+10% HP\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"Vũ khí khuyên dùng\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/597\"},\"cell\":{\"padTop\":50,\"row\":true,\"size\":[340,173],\"expandX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":24,\"text\":\"Rìu\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":24,\"text\":\"Bruk sở hữu sức chống chịu cùng khả năng phục hồi rất tốt, là tấm khiên chắn sát thương cho cả đội. Tương tác tốt với lối xây dựng trang bị tăng HP, Giáp và khả năng chống chịu ở tuyến đầu\",\"wrap\":true},\"cell\":{\"padLeft\":10,\"padBottom\":50,\"spaceTop\":20,\"row\":true,\"growX\":true}}]}', '[0.3,1.0,0.5,0.7]', 1),
