(0, 4, 5, 'Điểm tiềm năng', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Điểm tiềm năng\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Điểm tiềm năng có thể nhận được khi lên cấp hoặc sử dụng vật phẩm\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/151\"},\"cell\":{\"padTop\":35,\"size\":[80,88],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Sách tiềm năng (+ 1 Điểm tiềm năng)\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Sách tiềm năng có thể được tìm thấy khi đánh bại Siêu quái, Boss hoặc tham gia các hoạt động khác vv...\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Điểm tiềm năng sẽ được sử dụng để tăng các chỉ số nội tại\\n[#FFF600]- Sinh lực:[reset] Tiêu hao 1 điểm - Tăng HP\\n[#FFF600]- Trí lực:[reset] Tiêu hao 1 điểm - Tăng MP\\n[#FFF600]- Nhanh nhẹn:[reset] Tiêu hao 2 điểm - Tăng Né tránh\\n[#FFF600]- Tập trung:[reset] Tiêu hao 2 điểm - Tăng Chính xác\\n[#FFF600]- Bạo kích:[reset] Tiêu hao 2 điểm - Tăng Chí mạng\\n[#FFF600]- Sức mạnh:[reset] Tiêu hao 3 điểm - Tăng Tấn công\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Ngoài ra Điểm tiềm năng cũng được dùng để học và nâng cấp các kỹ năng giúp tăng sức mạnh chiến đấ