(0, 5, 6, 'Tiền tệ', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Tiền tệ\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tinh Linh Nguyên Thủy sử dụng 3 loại vật phẩm tiền tệ chính là Vàng, Vàng khóa và Lam thạch\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"height\":130,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/182\"},\"cell\":{\"padTop\":50,\"size\":[62,39],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/607\"},\"cell\":{\"padRight\":10,\"padTop\":50,\"size\":[63,44],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/181\"},\"cell\":{\"padRight\":35,\"padTop\":50,\"size\":[54,41],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Vàng\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Vàng khóa\",\"wrap\":true},\"cell\":{\"padRight\":10,\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Lam thạch\",\"wrap\":true},\"cell\":{\"padRight\":35,\"height\":40,\"growX\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]- Vàng:[reset] Thu thập thông qua các hoạt động hàng ngày như đánh Quái, đánh Boss, Mở rương, Tham gia Phụ bản, Trao đổi ký gửi, vv...\\nSử dụng để Mua các vật phẩm tại cửa hàng, Mua vật phẩm tại shop ký gửi, Nâng cấp trang bị, Đóng góp cho Bộ L