(0, 6, 7, 'Cây táo', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Cây táo\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Cây táo mọc cố định tại Nông trại, mỗi một khoảng thời gian cố định tùy theo cấp của cây táo sẽ cho ra 1 Quả táo. Người chơi có thể tới và thu hoạch để nhận được Quả táo\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/614\"},\"cell\":{\"padTop\":20,\"padRight\":35,\"size\":[300,301],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":24,\"text\":\"Cây táo\",\"wrap\":true},\"cell\":{\"padRight\":100,\"growX\":true,\"spaceBottom\":10,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Khi thu hoạch táo, người chơi sẽ nhận được ngẫu nhiên táo xanh, táo đỏ và có tỉ lệ nhỏ nhận được táo vàng\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":15,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/453\"},\"cell\":{\"padLeft\":5,\"padTop\":20,\"size\":[59,72]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Táo xanh - Giúp hồi phục một lượng MP\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/452\"},\"cell\":{\"padLeft\":5,\"padTop\":10,\"size\":[59,72]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Táo đỏ - Giúp hồi phục một lượng HP\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/451\"},\"cell\":{\"padLeft\":5,\"padTop\":10,\"size\":[59,72]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Táo vàng - Hồi lại 100% HP và MP\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Có thể sử dụng vàng để nâng cấp Cây táo giúp tăng khả năng hồi phục của Táo xanh và Táo đỏ đồng thời tăng tỉ lệ xuất hiện Táo vàng\\n\\nKhi nâng cấp, Cây táo sẽ cần 1 khoảng thời gian chờ để Cây táo hoàn tất việc nâng cấp và tiếp tục cho ra quả. Có thể dùng Lam thạch để đẩy nhanh quá trình nâng cấp Cây táo\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"spaceTop\":15,\"row\":true}}]}', NULL),
(0, 7, 8, 'Cường hóa trang bị', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Cường hóa trang bị\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]1 Nâng cấp trang bị[reset]\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Đến gặp ông Morgi tại làng ánh sáng Eldarah để sử dụng các tính năng cường hóa\",\"wrap\":true},\"cell\":{\"padTop\":5,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Thợ rèn\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Ông Morgi\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/629\"},\"cell\":{\"padTop\":20,\"row\":true,\"size\":[311,325],\"expandX\":true,\"spaceTop\":20}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Sử dụng 1 trong 2 loại đá cường hóa là Đá mặt Trời hoặc Đá mặt Trăng để nâng cấp trang bị\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"height\":135,\"padTop\":50,\"padRight\":50,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/154\"},\"cell\":{\"size\":[74,70],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/155\"},\"cell\":{\"size\":[57,68],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Đá mặt trời\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Đá mặt trăng\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Bỏ càng nhiều đá nâng cấp vào sẽ tăng tỉ lệ thành công. Tỉ lệ thành công tối đa sẽ giảm dựa trên cấp độ trang bị, càng lên cấp cao tỉ lệ thành công tối đa sẽ càng thấp\\nCấp tối đa của trang bị là cấp 10, trang bị từ cấp 2 trở lên khi nâng cấp thất bại sẽ giảm 1 cấp\\nKhi nguyên liệu đá đạt đủ tỉ lệ thành công tối đa có thể sử dụng bảo hiểm mua trực tiếp tại cửa hàng Thợ rèn để hạn chế rủi ro khi nâng cấp trang bị\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/175\"},\"cell\":{\"padLeft\":5,\"padTop\":50,\"size\":[74,76]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Bảo hiểm cấp 1[reset] - dành cho trang bị dưới cấp 5\",\"wrap\":true},\"cell\":{\"padTop\":30,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/174\"},\"cell\":{\"padLeft\":5,\"size\":[74,76]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Bảo hiểm cấp 2[reset] - dành cho mọi trang bị\",\"wrap\":true},\"cell\":{\"padBottom\":30,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Khi nâng cấp thành công trang bị sẽ lên 1 cấp đồng thời tăng 4% chỉ số hiện tại của trang bị\\nKhi mặc đủ 8 trang bị bao gồm Áo, Quần, Găng, Giày, Mũ, Đai lưng, Vòng cổ, Vũ khí mang cùng một trạng thái sẽ cho hiệu ứng đặc biệt\\n\\nĐá mặt trời sẽ cho hiệu ứng Nhật ấn giúp gia tăng chỉ số chiến đấu thiên về Tấn công, Thiêu đốt và Chí mạng\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/225\"},\"cell\":{\"padTop\":20,\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Nhật ấn I[reset]: Mặc 8 trang bị Nhật ấn từ cấp 3 trở lên\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/226\"},\"cell\":{\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Nhật ấn II[reset]: Mặc 8 trang bị Nhật ấn từ cấp 5 trở lên\",\"wrap\":true},\"cell\":{\"padBottom\":25,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/227\"},\"cell\":{\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Nhật ấn III[reset]: Mặc 8 trang bị Nhật ấn từ cấp 7 trở lên\",\"wrap\":true},\"cell\":{\"padBottom\":25,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChil