"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/232\"},\"cell\":{\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Nguyệt ấn IV[reset]: Mặc 8 trang bị Nguyệt ấn cấp 10\",\"wrap\":true},\"cell\":{\"padBottom\":25,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]2 Khảm Bùa linh hồn[reset]\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Mỗi 2 cấp độ trang bị sẽ mở khóa 1 ô khảm Bùa linh hồn, Có thể mua trực tiếp Bùa linh hồn tại cửa hàng Thợ rèn\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"height\":120,\"padTop\":50,\"padRight\":50,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/150\"},\"cell\":{\"row\":true,\"size\":[59,71],\"expandX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Cỏ may mắn\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Khảm Bùa linh hồn vào trang bị để gia tăng chỉ số chiến đấu, Sử dụng cỏ may mắn tăng tỉ lệ thành công và tránh rủi ro mất nguyên liệu\\nBùa linh hồn có thể gỡ ra khỏi trang bị khi cần thiết.\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/169\"},\"cell\":{\"padTop\":25,\"size\":[63,83]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":