\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/170\"},\"cell\":{\"padTop\":10,\"size\":[63,83]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Bùa linh hồn Thần xạ[reset] - Tăng Chính xác\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/166\"},\"cell\":{\"padTop\":10,\"size\":[63,83]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Bùa linh hồn Xuyên Phá[reset] - Tăng Xuyên giáp\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/163\"},\"cell\":{\"padTop\":10,\"size\":[63,83]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Bùa linh hồn Tốc độ[reset] - Tăng Né tránh\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/164\"},\"cell\":{\"padTop\":10,\"size\":[63,83]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Bùa linh hồn Phản kích[reset] - Tăng Phản sát thương\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]3 Khảm đá Nguyên Tố[reset]\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Mỗi 2 cấp độ trang bị sẽ mở khóa 1 ô khảm đá Nguyên tố, có thể thu thập thông qua các hoạt động của như Đánh quái, Săn boss, v.v...\\n\\nĐá Nguyên Tố có thể khảm vào trang bị và tăng nhiều cấp độ khảm. Cấp độ càng cao, lượng đá cần tiêu hao càng nhiều, có thể sử dụng cỏ may mắn tăng tỉ lệ thành công và tránh rủi ro mất nguyên liệu\\nĐá Nguyên tố có thể gỡ ra khỏi trang bị khi cần thiết nhưng sẽ tiêu hao 50% số lượng đá\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/158\"},\"cell\":{\"padTop\":35,\"size\":[65,65]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Đá Nguyên tố Kim[reset] - Tăng Sát thương chí mạng\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/157\"},\"cell\":{\"padTop\":15,\"size\":[66,63]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Đá Nguyên tố Mộc[reset] - Tăng Giáp\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/156\"},\"cell\":{\"padTop\":15,\"size\":[63,66]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Đá Nguyên tố Thủy[reset] - Tăng MP\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/160\"},\"cell\":{\"padTop\":15,\"size\":[65,65]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Đá Nguyên tố Hỏa[reset] - Tăng Tấn công\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/159\"},\"cell\":{\"padTop\":15,\"size\":[63,64]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Đá Nguyên tố Thổ[reset] - Tăng HP\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/161\"},\"cell\":{\"padTop\":15,\"size\":[67,68]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Đá Nguyên tố Phong[reset] - Tăng Kháng sát thương\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/162\"},\"cell\":{\"padTop\":15,\"size\":[67,66]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":8,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Đá Nguyên tố Lôi[reset] - Tăng Né tránh\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]}]}', NULL),
(0, 8, 9, 'Chuyển hóa Trang bị', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Chuyển hóa Trang bị\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Cho phép chuyển toàn bộ cấp cường hóa từ một trang bị sang trang bị khác. Trang bị nhận chuyển hóa sẽ kế thừa cấp cường hóa của trang bị được chọn, giúp người chơi thay đổi hoặc nâng cấp trang bị mới mà không phải cường hóa lại từ đầu.\\n\\nTới Làng ánh sáng Eldarah gặp ông Thợ rèn Morgi để sử dụng tính năng Chuyển hóa trang bị\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Thợ rèn\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Ông Morgi\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/629\"},\"cell\":{\"padTop\":20,\"row\":true,\"size\":[311,325],\"expandX\":true,\"spaceTop\":20}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Sử dụng Bùa chuyển hóa (Mua tại cửa hàng ông Tư tế Buraen) để Chuyển hóa trang bị\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/790\"},\"cell\":{\"size\":[64,71],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Bùa chuyển hóa\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Dùng một trang bị đã cường hóa Nhật ấn hoặc Nguyệt ấn để chuyển hóa toàn bộ cấp cường hóa sang một trang bị mới chưa cường hóa\\nCó thể sử dụng cỏ may mắn để tăng tỉ lệ thành công\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Lưu ý quan trọng[reset]\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"- Sau khi chuyển hóa, trang bị cũ sẽ bị phá hủy và biến mất\\n- Phải tháo hết tất cả Đá nguyên tố và Bùa linh hồn ở trang bị\\n[#FFF600]- Trang bị cấp Thủ lĩnh và Vũ khí Lục linh không thể chuyển hóa[reset]\\n- Chỉ có thể chuyển hóa trang bị cùng loại (ví dụ: Áo chỉ có thể chuyển hóa sang Áo không thể chuyển hóa sang Quần)\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}}]}', NULL);
INSERT INTO `guide_topic` (`category_idx`, `idx`, `id`, `name`, `layout_json`, `rewards`) VALUES
(0, 9, 10, 'Luyện tập Offline', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Luyện tập Offline\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Ngay cả khi chiến binh rời game, hành trình rèn luyện vẫn chưa dừng lại. Luyện tập Offline ủy thác nhân vật cho máy chủ, trong thời gian ủy thác, nhân vật sẽ tự động chiến đấu và tích lũy các phần thưởng như kinh nghiệm và vật phẩm mà không cần duy trì kết nối với game.\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Để sử dụng tính năng Luyện tập Offline, người chơi cần sở hữu tiện ích của Huy hiệu Tinh linh (Mua tại cửa hàng ông Tư tế Buraen)\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/446\"},\"cell\":{\"size\":[87,76],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Huy hiệu Tinh linh\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Khi sở hữu Huy hiệu Tinh linh, người chơi có thể chọn Menu cài đặt ở trên màn hình sau đó chọn Thiết lập để cài đặt tùy chỉnh tự động đánh\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"ui/81\"},\"cell\":{\"size\":[113,95],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Thiết lập các thông số và cài đặt phù hợp với nhân vật sau đó bấm Luyện tập Offline để đăng xuất và ủy thác nhân vật của bạn luyện tập Offline\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/949\"},\"cell\":{\"size\":[642,381],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Lưu ý quan trọng[reset]\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"- Hãy chuẩn bị Cỏ hồi sinh, Táo và Đùi gà trước khi ủy thác để quá trình Luyện tập Offline không bị gián đoạn\\n- Thời gian luyện tập Offline không giới hạn nhưng quá trình luyện tập sẽ kết thúc khi hết thời gian sử dụng Huy hiệu tinh linh\\n- Luyện tập Offline là tính năng ủy thác luyện tập cho máy chủ. Máy chủ sẽ điều khiển nhân vật của bạn luyện tập vì vậy hoàn toàn không có rủi ro mất Tài khoản\\n- Khi muốn quay trở lại chỉ cần đăng nhập vào tài khoản, hệ thống sẽ trả lại quyền truy cập\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}}]}', NULL),
(0, 10, 11, 'Cửa hàng ký gửi', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Cửa hàng ký gửi\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Các vật phẩm không khóa có thể gửi lên để trao đổi với người chơi khác tại cửa hàng ký gửi\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"ui/80\"},\"cell\":{\"size\":[113,95],\"align\":1,\"spaceTop\":35,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Cửa hàng ký gửi\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Người chơi có thể bán vật phẩm với giá trị tùy ý bằng cách nhập giá bán. Sau đó gửi vật phẩm lên cửa hàng ký gửi với kỳ hạn 8h, 16h, 24h. Mỗi kỳ hạn sẽ có mức phí ký gửi khác nhau.\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/603\"},\"cell\":{\"size\":[297,469],\"align\":1,\"spaceTop\":35,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Sau khi gửi lên cửa hàng ký gửi, người chơi khác sẽ nhìn thấy vật phẩm của bạn và có thể mua vật phẩm đó.\\n\\n      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - \",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Có thể sử dụng 1 Tù và mua tại cửa hàng Tạp hóa Selami để rao bán vật phẩm lên Kênh thế giới.\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/572\"},\"cell\":{\"size\":[80,57],\"align\":1,\"spaceTop\":50,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tù và\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tiền bán vật phẩm sau khi trừ phí Ký gửi sẽ được gửi về Thư cho người bán\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"ui/76\"},\"cell\":{\"size\":[113,95],\"align\":1,\"spaceTop\":35,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Hòm thư\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Cửa hàng ký gửi có giới hạn tối đa là [#FFF600]300 vật phẩm[reset]. Mỗi ngày mỗi người chỉ được bán miễn phí 5 vật phẩm lên Cửa hàng ký gửi, nếu bán vật phẩm thứ 6 trở lên sẽ tiêu hao 15 điểm năng động cho mỗi lượt bán vật phẩm lên Cửa hàng ký gửi\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}}]}', NULL),
(0, 11, 12, 'Tổ đội', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Tổ đội\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tổ đội cho phép người chơi hợp sức chiến đấu. Khi đứng ở gần nhau các thành viên sẽ chia sẻ 5% kinh nghiệm nhận được cho các thành viên khác trong tổ đội\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"ui/84\"},\"cell\":{\"size\":[113,95],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tổ đội\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tham gia tổ đội bằng cách xin vào tổ đội lân cận hoặc tự tạo tổ đội\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":10,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/605\"},\"cell\":{\"size\":[687,332],\"align\":1,\"spaceTop\":30,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Người tạo nhóm sẽ là trưởng nhóm, là người có quyền duyệt thành viên, đuổi thành viên hoặc giải tán nhóm.\\nNếu để chế độ tự động duyệt thành viên tổ đội thì bất cứ ai cũng sẽ có thể tự do ra vào nhóm của bạn\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":10,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/606\"},\"cell\":{\"padRight\":5,\"size\":[677,55],\"align\":1,\"spaceTop\":50,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Ngũ Linh Liên Vũ[reset]\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Khi trong tổ đội có đủ 5 chiến binh sử dụng 5 loại vũ khí khác nhau, sức mạnh Ngũ Linh sẽ được kích hoạt, mang lại các hiệu ứng đặc biệt:\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]- Giáo[reset] +5% Tấn công lên quái\\n[#FFF600]- Rìu[reset] +5% Hút MP quái\\n[#FFF600]- Roi da[reset] +5% Hút HP quái\\n[#FFF600]- Cung tên[reset] +5% Thưởng kinh nghiệm\\n[#FFF600]- Ná thun[reset] +5% Thưởng vàng[reset]\",\"wrap\":true},\"cell\":{\"padTop\":15,\"growX\":true,\"row\":true}}]}', NULL),
(0, 12, 13, 'Bộ lạc', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Bộ lạc\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Bộ Lạc là nơi quy tụ những chiến binh cùng chí hướng. Cùng đồng đội xây dựng Bộ Lạc, tham gia các hoạt động, săn Boss, chinh phục phụ bản và khẳng định vị thế trên vùng đất Khởi nguyên.\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"ui/86\"},\"cell\":{\"size\":[113,95],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Gia nhập Bộ lạc[reset]\",\"wrap\":true},\"cell\":{\"padTop\":25,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tham gia Bộ lạc bằng cách xin vào một Bộ lạc và chờ Tù trưởng phê duyệt hoặc tạo một bộ lạc của riêng mình bằng Cờ lệnh Bộ lạc (Mua tại cửa hàng tư tế)\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":10,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/152\"},\"cell\":{\"size\":[104,104],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Cờ lệnh Bộ lạc\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Người tạo Bộ lạc sẽ là Tù trưởng, là người có quyền duyệt thành viên, đuổi thành viên, sử dụng ngân sách Bộ lạc, Phân phát vật phẩm và giải tán Bộ lạc.\\nTù trưởng có thể bổ nhiệm cho người chơi khác trở thành phó Tù trưởng, người có quyền duyệt thành viên và đuổi thành viên.\\nCác thành viên khác sẽ có nhưng Danh hiệu riêng dựa theo sự đóng góp dành cho Bộ lạc\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":10,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/721\"},\"cell\":{\"padTop\":25,\"size\":[39,39]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Tù trưởng:[Reset] Là người tạo ra Bộ lạc, nắm quyền điều hành cao nhất trong Bộ lạc\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/722\"},\"cell\":{\"padTop\":25,\"size\":[39,39]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Phó tù trưởng:[Reset] Là người được Tù trưởng bổ nhiệm, có quyền phê duyệt hoặc đuổi thành viên\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/723\"},\"cell\":{\"padTop\":25,\"size\":[39,39]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Công thần:[Reset] Là người có nhiều điểm cống hiến nhất trong bộ lạc(Danh hiệu này không do Tù trưởng bổ nhiệm)\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/724\"},\"cell\":{\"padTop\":25,\"size\":[39,39]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Tài chủ:[Reset] Là người đóng góp nhiều Lam thạch nhất cho bộ lạc (Danh hiệu này không do Tù trưởng bổ nhiệm)\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/725\"},\"cell\":{\"padTop\":25,\"size\":[39,39]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Kim chủ:[Reset] Là người đóng góp nhiều Vàng nhất cho bộ lạc(Danh hiệu này không do Tù trưởng bổ nhiệm)\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Kỹ năng bộ lạc[reset]\",\"wrap\":true},\"cell\":{\"padTop\":35,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Các thành viên trong Bộ lạc sẽ tham gia các hoạt động hàng ngày để nhận về điểm Cống hiến Bộ lạc. Khi đủ điếm cống hiến cần thiết, Bộ lạc sẽ lên cấp.\\nVới mỗi cấp độ của Bộ lạc, Tù trưởng có thể sử dụng Vàng trong ngân sách Bộ lạc để mở khóa một kỹ năng ngẫu nhiên mới và hiệu ứng của kỹ năng đó sẽ có tác dụng lên tất cả các thành viên trong bộ lạc.\\nCó thể sử dụng vàng để đổi kỹ năng khác nếu cảm thấy kỹ năng hiện tại không phù hợp.\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":10,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/671\"},\"cell\":{\"padTop\":25,\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Huyết Tế Cuồng Nộ:[Reset] Tăng 10% Tấn công khi dưới 50% HP\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/674\"},\"cell\":{\"padTop\":25,\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Hợp Nhất Tinh Thần:[Reset] Tăng 100 Giáp khi đừng cạnh 1 thành viên cùng bang hội (tối đa 2000)\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/666\"},\"cell\":{\"padTop\":25,\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Dấu Ấn Thợ Săn:[Reset] Tăng 500 Chí mạng và 500 Chính xác\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/673\"},\"cell\":{\"padTop\":25,\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Học Giả Bộ Lạc:[Reset] Tăng 2% Thưởng kinh nghiệm nhận khi đứng cạnh 1 thành viên cùng bang hội (tối đa 20%)\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/668\"},\"cell\":{\"padTop\":25,\"size\":[85,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"[#FFF600]Cường Hóa Tinh Thần:[Reset] Tăng 2% Hấp thụ sát thương\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeC