(1, 0, 1, 'Quái & Siêu quái', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Quái & Siêu quái\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Quái thường là những sinh vật mang sức mạnh tự nhiên, không quá nguy hiểm nhưng vẫn đủ gây khó khăn. Đánh bại chúng để nhận Kinh nghiệm và Vàng\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"minHeight\":150,\"spaceTop\":20,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/612\"},\"cell\":{\"padRight\":35,\"size\":[188,124],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":24,\"text\":\"Quái thường\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceBottom\":10,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Khi đánh bại 1 Quái thường, chúng sẽ có tỉ lệ trở lại với sức mạnh vượt trội và trở thành Siêu Quái\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":1,\"font\":2,\"fontSize\":22,\"text\":\"Siêu quái có 2 dạng là\",\"wrap\":true},\"cell\":{\"padTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"height\":200,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/602\"},\"cell\":{\"padTop\":50,\"size\":[188,160],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/601\"},\"cell\":{\"padTop\":50,\"size\":[188,160],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Quái Tinh anh\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Quái Thủ lĩnh\",\"wrap\":true},\"cell\":{\"height\":40,\"growX\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Đánh bại Siêu quái sẽ nhận được điểm chiến binh, điểm hoạt động và rơi ra nhiều vật phẩm quý hiểm\\n\\n      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - \\n\\nNếu level của người chơi và level của quái chênh lệch 10 cấp độ thì sát thương lên quái sẽ bị giảm 80% và nếu chênh lệch 15 cấp độ thì sẽ không rơi vật phẩm\",\"wrap\":true,\"adjustLineHeight\":2},\"cell\":{\"growX\":true,\"spaceTop\":50,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/613\"},\"cell\":{\"padTop\":35,\"size\":[356,54],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Thanh hiển thị HP, Level và tên của Quái\",\"wrap\":true},\"cell\":{\"padTop\":5,\"growX\":true,\"spaceBottom\":10,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Phần thưởng\",\"wrap\":true},\"cell\":{\"growX\":true,\"height\":30,\"space\":[30,0,30,0],\"row\":true}},{\"type\":\"scrollpane\",\"typeChild\":1,\"cell\":{\"height\":120,\"width\":720,\"row\":true,\"spaceTop\":50},\"childrens\":[{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":0},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":1},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":2},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":3},\"cell\":{\