(1, 1, 2, 'Vệ thần & Tinh linh', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Vệ thần & Tinh linh\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Lục địa Eldarah rộng lớn được có nhiều vùng đất khác nhau, mỗi vùng đất đều có các vị thần ngự trị cai quản\\n- [#FFF600]Tinh linh (Boss)[reset] là thực thể tối cao duy trì năng lượng ổn định của vùng đất đó\\n- [#FFF600]Vệ thần (Mini Boss)[reset] là Hung thần khổng lồ bảo vệ vùng đất khỏi những kẻ xâm nhập.\\nMỗi vùng đất đều 2 thực thể cùng tồn tại, bổ trợ và phối hợp cùng nhau duy trì sự ổn định của vùng đất đó\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Rừng Sayari[reset]\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Ẩn sâu bên trong Rừng Sayari cổ xưa tồn tại hai thực thể tối cao được người dân bộ tộc thờ phụng nhau qua nhiều thế hệ đó là [#FFF600]Vệ thần Rừng Xanh[reset] và [#FFF600]Tinh linh Rừng Xanh[reset]. Họ là những vị thần đã tồn tại từ thời trước khi những người dân đầu tiên của Bộ tộc Sayari đặt chân đến, lặng lẽ canh giữ sự sống và cân bằng của khu rừng nguyên thủy\",\"wrap\":true},\"cell\":{\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/608\"},\"cell\":{\"padTop\":20,\"size\":[340,349],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Vệ thần Rừng xanh\",\"wrap\":true},\"cell\":{\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/755\"},\"cell\":{\"padRight\":35,\"padTop\":177,\"size\":[239,192],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tinh linh Rừng xanh\",\"wrap\":true},\"cell\":{\"padRight\":35,\"growX\":true}}]}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Đầm lầy Avenna[reset]\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Đầm lầy Avenna chứa đầy ma lực cổ xưa, tồn tại hai thực thể mang sức mạnh vượt ngoài hiểu biết của con người đó là [#FFF600]Vệ thần Đầm Lầy[reset] và [#FFF600]Tinh linh Đầm Lầy[reset]. Thực thể được sinh ra từ dòng chảy ma pháp tích tụ qua hàng ngàn năm dưới lòng Avenna, trở thành những kẻ canh giữ sự cân bằng giữa sự sống và nguồn ma lực đang không ngừng lan rộng khắp đầm lầy\",\"wrap\":true},\"cell\":{\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/743\"},\"cell\":{\"padTop\":20,\"size\":[423,398],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Vệ thần Đầm lầy\",\"wrap\":true},\"cell\":{\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/746\"},\"cell\":{\"padRight\":35,\"padTop\":254,\"size\":[182,164],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tinh linh Đầm lầy\",\"wrap\":true},\"cell\":{\"padRight\":35,\"growX\":true}}]}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Làng chài Velmora[reset]\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Velmora là một Làng chài yên bình, vùng đất này tồn tại các thực thể cổ xưa mang sức mạnh của Đại dương đó là [#FFF600]Vệ thần Biển Cả[reset] và [#FFF600]Tinh linh Biển Cả[reset], là hiện thân của sóng nước và linh khí biển khơi, duy trì sự cân bằng của Đại dương. Ngư dân nơi đây thờ phụng và tin rằng họ được biển cả che trở, cá tôm dồi dào và những con thuyền có thể bình an trở về\",\"wrap\":true},\"cell\":{\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/744\"},\"cell\":{\"padTop\":20,\"size\":[361,322],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Vệ thần Biển cả\",\"wrap\":true},\"cell\":{\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/757\"},\"cell\":{\"padRight\":35,\"padTop\":163,\"size\":[188,179],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tinh linh Biển cả\",\"wrap\":true},\"cell\":{\"padRight\":35,\"growX\":true}}]}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Cao nguyên Darguun[reset]\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tuyền thuyết của người Dargun có kể về các thực thể tối cao của vùng đất đó là [#FFF600]Vệ thần Phong thạch[reset] và [#FFF600]Tinh linh Phong thạch[reset]. Họ tin rằng đó chính là linh hồn của Cao nguyên. Thực thể nắm giữ sức mạnh của đất đá và gió ngủ yên trong lòng núi. Chỉ khi một chiến binh đủ mạnh xuất hiện, ý chí của người đó sẽ đánh thức những thực thể ấy khỏi giấc ngủ ngàn năm\",\"wrap\":true},\"cell\":{\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/742\"},\"cell\":{\"padTop\":20,\"size\":[369,304],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Vệ thần Phong thạch\",\"wrap\":true},\"cell\":{\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/756\"},\"cell\":{\"padRight\":35,\"padTop\":129,\"size\":[235,195],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tinh linh Phong thạch\",\"wrap\":true},\"cell\":{\"padRight\":35,\"growX\":true}}]}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]Núi tuyết Frearh[reset]\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Khi những cơn bão tuyết đầu tiên bao trùm Frearh, Hàn Băng Vĩnh Cửu cũng tạo nên thực thể mang sức mạnh cổ xưa. [#FFF600]Vệ thần Băng Giá[reset] và [#FFF600]Tinh linh Băng Giá[reset] tồn tại giữa biển tuyết lạnh giá như những kẻ canh giữ bất tận, giữ cho hàn khí cổ đại luôn nằm trong vòng cân bằng, không nuốt chửng toàn bộ sự sống nơi băng nguyên lạnh giá\",\"wrap\":true},\"cell\":{\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/745\"},\"cell\":{\"padTop\":20,\"size\":[351,270],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Vệ thần Băng giá\",\"wrap\":true},\"cell\":{\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/747\"},\"cell\":{\"padRight\":35,\"padTop\":128,\"size\":[205,162],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tinh linh Băng giá\",\"wrap\":true},\"cell\":{\"padRight\":35,\"growX\":true}}]}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Phần thưởng\",\"wrap\":true},\"cell\":{\"growX\":true,\"height\":30,\"space\":[30,0,30,0],\"row\":true}},{\"type\":\"scrollpane\",\"typeChild\":1,\"cell\":{\"height\":120,\"width\":720,\"row\":true,\"spaceTop\":50},\"childrens\":[{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":0},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":1},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":2},\"cell\":{\"e