(1, 2, 3, 'Tinh luyện Đá khởi nguyên', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Tinh luyện Đá khởi nguyên\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Đá khởi nguyên là những khối đá cổ xưa mang trong mình hai nguồn linh lực Nhật Nguyệt đối lập xuất hiện khắp lục địa Eldarah.\\nNgười chơi có thể thu thập Đá khởi nguyên bằng cách Đánh bại Quái, Siêu Quái và Boss, vv... Hoặc tham Gia các hoạt động hàng ngày như Điểm danh, nhận quà Online, tham gia Giải đấu Bộ lạc, Tham gia phụ bản, Làm nhiệm vụ hàng ngày, vv...\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/610\"},\"cell\":{\"row\":true,\"size\":[66,48],\"expandX\":true,\"spaceTop\":20}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Đá khởi nguyên\\n\\n      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - \",\"wrap\":true},\"cell\":{\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tới Thợ rèn dùng 10 viên Đá khởi nguyên để tinh luyện thành 1 Đá mặt Trời hoặc 1 Đá mặt Trăng tùy chọn - Sử dụng để nâng cấp trang bị giúp tăng sức mạnh chiến đấu\",\"wrap\":true},\"cell\":{\"row\":true,\"growX\":true,\"spaceTop\":20}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Thợ rèn\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Ông Morgi\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/629\"},\"cell\":{\"padTop\":20,\"row\":true,\"size\":[311,325],\"expandX\":true,\"spaceTop\":20}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Phần thưởng\",\"wrap\":true},\"cell\":{\"growX\":true,\"height\":30,\"space\":[30,0,30,0],\"row\":true}},{\"type\":\"scrollpane\",\"typeChild\":1,\"cell\":{\"height\":120,\"width\":720,\"row\":true,\"spaceTop\":50},\"childrens\":[{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":0},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,250,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":1},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}}]}]}', '[{\"i\":125,\"l\":1},{\"i\":126,\"l\":1}]');
