(1, 3, 4, 'Chế tác vũ khí Linh thạch', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Chế tác vũ khí Linh thạch\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Các vũ khí được chế tác từ đá Bất hoại và đá Lục linh cần được tạo ra từ các mảnh vỡ thu thập trong nhiều hoạt động hằng ngày như Câu cá, Giải đấu Bộ lạc, Tiêu diệt Boss hoặc mở Túi đá linh thạch\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/584\"},\"cell\":{\"size\":[66,65],\"align\":1,\"spaceTop\":50,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Túi đá linh thạch\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Bên trong có chứa 1 mảnh vũ khí Linh thạch ngẫu nhiên bao gồm có:\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":15,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/222\"},\"cell\":{\"padTop\":35,\"size\":[80,43]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Mảnh Rìu bất hoại\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"padLeft\":10,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/216\"},\"cell\":{\"padTop\":20,\"size\":[74,36]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Mảnh Giáo bất hoại\",\"wrap\":true},\"cell\":{\"growX\":true,\"padLeft\":10,\"row\":true}},{\"type\":\"table\",