(1, 4, 5, 'Câu cá', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Câu cá\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Dòng sông từ thượng nguồn Eldara chảy quanh lục địa mang theo sự sống cùng rất nhiều tài nguyên cho người dân.\\nTại bất kỳ vị trí nào dọc bờ sông, người chơi đều có thể thả cần để câu cá.\\nCó thể mua Cần câu tại cửa hàng Thợ rèn và mua Mồi câu tại cửa hàng Tạp hóa.\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/121\"},\"cell\":{\"size\":[94,88],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Cần câu\",\"wrap\":true},\"cell\":{\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/144\"},\"cell\":{\"padRight\":35,\"padTop\":15,\"size\":[80,72],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Mồi câu\",\"wrap\":true},\"cell\":{\"padRight\":35,\"growX\":true}}]}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":1,\"font\":2,\"fontSize\":22,\"text\":\"Khi câu cá sẽ tiêu hao 1 Mồi câu.\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Khi cá cắn câu, người chơi phải căn đúng vị trí để kéo cần câu.\\nNếu kéo cần câu ở vùng Vàng sẽ nhận được vật phẩm bình thường.\\nNếu kéo cần câu ở vùng Xanh sẽ có cơ hội nhận được vật phẩm hiếm.\\nNếu kéo trượt sẽ không nhận được vật phẩm.\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/611\"},\"cell\":{\"padTop\":20,\"size\":[504,42],\"align\":1,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Câu cá\\n\\n      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - \",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Có thể bán trực tiếp số cá để nhận Vàng hoặc tích đủ số lượng Cá để đổi lấy những vật phẩm quý hiếm tại Dân làng Tarae\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":10,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Dân làng\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tarae\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/651\"},\"cell\":{\"padTop\":20,\"row\":true,\"size\":[190,242],\"expandX\":true,\"spaceTop\":20}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Phần thưởng\",\"wrap\":true},\"cell\":{\"growX\":true,\"height\":30,\"space\":[30,0,30,0],\"row\":true}},{\"type\":\"scrollpane\",\"typeChild\":1,\"cell\":{\"height\":120,\"width\":720,\"row\":true,\"spaceTop\":50},\"childrens\":[{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":0},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,20,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"proper