(1, 5, 6, 'Săn bắt & Hái lượm', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Săn bắt & Hái lượm\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Lục địa Ehdarah trù phú giàu tài nguyên thiên nhiên. Từ xa xưa, các bộ tộc đã sinh tồn bằng hoạt động hái lượm và săn bắt, tìm kiếm lương thực, dược liệu và nguyên liệu chế tác giữa thiên nhiên rộng lớn\\n\\n      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - \",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]1 Hái lượm[reset]\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Trên khắp thảo nguyên Eldarah trù phù có các Loại quả mọng, Cỏ hồi sinh, Nấm hương xuất hiện rải rác với nhiều tác dụng khác nhau. Người chơi có thể đi tìm để thu hoạch và sử dụng chúng\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/617\"},\"cell\":{\"padTop\":25,\"size\":[89,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Quả mọng đỏ: Xuất hiện tại các map trên thảo nguyên Eldarah - Sử dụng để hồi lại một phần thể lực\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/618\"},\"cell\":{\"padTop\":15,\"size\":[89,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Quả mọng tím: Xuất hiện tại các map trên thảo nguyên Eldarah - Sử dụng để hồi lại một phần HP và MP\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/615\"},\"cell\":{\"padTop\":15,\"size\":[89,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Cỏ hồi sinh: Xuất hiện tại các map trên thảo nguyên Eldarah - Sử dụng để hồi lại sức lực khi bị hạ gục\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/616\"},\"cell\":{\"padTop\":15,\"size\":[89,85]}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Nấm hương: Xuất hiện tại các map trong khu rừng Sayari - Sử dụng để tăng khả năng hồi HP và MP\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"padLeft\":10,\"row\":true}}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]2 Nuôi Heo con[reset]\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tại Nông trại của làng ánh Sáng có thể thả Heo rừng con. Heo rừng con là giống Heo đã được thuần hóa hoàn toàn, có thể nuôi để lấy Thịt heo\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/710\"},\"cell\":{\"padTop\":20,\"row\":true,\"size\":[188,120],\"expandX\":true,\"spaceTop\":20}},{\