(1, 6, 7, 'Pha chế ma thuật', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Pha chế Ma thuật\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tại vùng đầm lầy Avenna, nơi ma thuật và linh khí mạnh mẽ, có những loài hoa ma thuật mọc rải rác.\",\"wrap\":true},\"cell\":{\"padTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"row\":true,\"growX\":true,\"spaceTop\":20},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/619\"},\"cell\":{\"size\":[122,126],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/620\"},\"cell\":{\"size\":[122,126],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/621\"},\"cell\":{\"size\":[122,126],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Hoa Tử nguyệt\",\"wrap\":true},\"cell\":{\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Hoa Huyết lan\",\"wrap\":true},\"cell\":{\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Hoa Mộc diên\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/622\"},\"cell\":{\"padTop\":25,\"size\":[122,126],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/623\"},\"cell\":{\"padTop\":25,\"size\":[122,126],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/624\"},\"cell\":{\"padTop\":25,\"size\":[122,126],\"expandX\":true,\"row\":true}},{\"type\":\"label\"