(1, 8, 9, 'Cáo trộm vàng', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Cáo trộm vàng\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tiêu Tinh linh cáo là loài sinh vật nhỏ bé nhưng cực kỳ nhanh nhẹn, chúng lang thang trên khắp lục địa Eldarah rình rập những kẻ mang theo nhiều vàng trên người, Chúng thường lặng lẽ tiếp cận mục tiêu, nhanh tay cuỗm đi một phần vàng rồi biến mất chỉ trong chớp mắt\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/711\"},\"cell\":{\"row\":true,\"size\":[105,112],\"expandX\":true,\"spaceTop\":50}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tiểu Tinh linh Cáo\",\"wrap\":true},\"cell\":{\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tiểu Tinh linh Cáo sẽ lấy trộm một ít vàng của người chơi và sẽ dừng lại nếu túi vàng của chúng đã đầy. Đánh hạ tiểu Tinh linh Cáo sẽ rơi ra toàn bộ số vàng mà chúng đã lấy trộm của người chơi ngoài còn nhận được Điểm hoạt động và Điểm cống hiến Bộ lạc\",\"wrap\":true},\"cell\":{\"row\":true,\"growX\":true,\"spaceTop\":20}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Phần thưởng\",\"wrap\":true},\"cell\":{\"growX\":true,\"height\":30,\"space\":[30,0,30,0],\"row\":true}},{\"type\":\"scrollpane\",\"typeChild\":1,\"cell\":{\"height\":120,\"width\":720,\"row\":true,\"spaceTop\":50},\"childrens\":[{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":0},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,310,5,5]}}]}]}', '[{\"i\":1}]'),
(1, 9, 10, 'Giải đấu Bộ lạc', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Giải đấu Bộ lạc\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":40,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Giải đấu Bộ lạc được tổ chức hằng ngày với nhiều giải đấu khác nhau để chọn ra người chiến binh mạnh nhất thống lĩnh Bộ lạc\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]- Giải Nhi đồng[reset]\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Yêu cầu chiến binh từ cấp 5 - 25\\nThời gian mở đăng kí: 9h00 - 9h25\\nBắt đầu lúc: 9h30\\nLệ phí đăng kí [#FFF600]50.000[reset] vàng\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]- Giải Chiến binh[reset]\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Yêu cầu chiến binh từ cấp 26 - 45\\nThời gian mở đăng kí: 12h00 - 12h25\\nBắt đầu lúc: 12h30\\nLệ phí đăng kí [#FFF600]200.000[reset] vàng\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]- Giải Thủ lĩnh[reset]\",\"wrap\":true},\"cell\":{\"padTop\":10,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Yêu cầu chiến binh từ cấp 46 trở lên\\nThời gian mở đăng kí: 17h00 - 17h25\\nBắt đầu lúc: 17h30\\nLệ phí đăng kí [#FFF600]500.000[reset] vàng\\n\\nCác chiến binh sẽ đăng kí tại Tư tế Buraen ở Làng ánh sáng. Mỗi giải đấu có số lượng người đăng kí tối đa là 400 người\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Tư tế\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Ông Buraen\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/609\"},\"cell\":{\"padTop\":35,\"size\":[190,285],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Người đăng kí sẽ tập trung ở Làng ánh sáng Eldarah, nếu không có mặt tại Làng khi trận đấu bắt đầu thì sẽ bị tính là bỏ cuộc và bị loại. Khi trận đấu bắt đầu Tư tế sẽ đưa tất cả tới thượng nguồn Eldarah.\\n\\n      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - \",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Người chơi sẽ được xếp cặp ngẫu nhiên để thi đấu 1 vs 1 với người chơi khác - Người chiến thắng sẽ được vào vòng trong, người thua cuộc sẽ bị loại và được đưa trở về làng\\nChiến thắng mỗi vòng đấu sẽ nhận được Phần thưởng Vòng, người vô địch sẽ nhận được thêm Phần thưởng.\\n\\nPhần thưởng của giải đấu sẽ được gửi trực tiếp về Hòm thư.\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]- Giải Anh hùng[reset]\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Yêu cầu chiến binh từ cấp 5 trở lên\\nThời gian diễn ra: 20h00 Thứ 2, 4, 6 Hàng tuần\\nCác chiến binh sẽ gặp Tư tế Buraen ở Làng ánh sáng để tới tập trung tại thượng nguồn Eldarah\\nĐúng 20h15 - vòng loại sẽ diễn ra, các chiến binh có mặt tại võ đài sẽ chuyển sang trạng thái chiến tranh và có thể tấn công lẫn nhau\\nHạ gục người chơi khác sẽ nhận được 1 điểm, bị người chơi khác hạ gục sẽ tự động được hồi sinh sau 3 giây, nếu bị hạ gục quá 20 lần sẽ bị loại ngay lập tức và được đưa về Làng\\nVòng loại sẽ diễn ra trong 10 phút. Đúng 20h25, 16 người có số điểm cao nhất sẽ được vào vòng trong và được xếp cặp ngẫu nhiên để thi đấu 1 vs 1 với người chơi khác - Người chiến thắng sẽ tiếp tục được vào vòng trong, người thua cuộc sẽ bị loại và được đưa về làng\\n\\nChiến thắng mỗi vòng đấu sẽ nhận được Phần thưởng Vòng, người vô địch sẽ nhận được thêm Phần thưởng Vô địch và Danh hiệu tương ứng.\\n\\nPhần thưởng của giải đấu sẽ được gửi trực tiếp về Hòm thư.\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":26,\"text\":\"[#FFF600]- Giải Hợp chiến\",\"wrap\":true},\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Yêu cầu chiến binh từ cấp 5 trở lên và đang ở trong tổ đội\\nThời gian diễn ra: 20h00 Thứ 3, 5, 7 Hàng tuần\\nCác tổ đội sẽ gặp Tư tế Buraen ở Làng ánh sáng để tới tập trung tại thượng nguồn Eldarah\\nĐúng 20h15 - vòng loại sẽ diễn ra, các tổ đội có mặt tại võ đài sẽ chuyển sang trạng thái chiến tranh và có thể tấn công lẫn nhau\\nHạ gục người chơi khác sẽ nhận được 1 điểm, bị người chơi khác hạ gục sẽ tự động được hồi sinh sau 3 giây, nếu bị hạ gục quá 20 lần sẽ bị loại ngay lập tức và được đưa về Làng\\nVòng loại sẽ diễn ra trong 10 phút. Đúng 20h25, 16 tổ đội có số điểm cao nhất sẽ được vào vòng trong và được xếp cặp ngẫu nhiên để thi đấu 5 vs 5 với tổ đội khác - Tổ đội chiến thắng sẽ tiếp tục được vào vòng trong, tổ đội thua cuộc sẽ bị loại và được đưa về làng\\n\\nNếu 1 thành viên bị loại, tổ đội vẫn có thể đi tiếp và không có mặt của thành viên đó, khi tất cả thành viên trong tổ đội bị loại thì tổ đội đó mới chính thức bị loại.\\n\\nChiến thắng mỗi vòng đấu cả tổ đội (trừ thành viên đã bị loại) sẽ nhận được Phần thưởng Vòng, đội vô địch sẽ nhận được thêm Phần thưởng Vô địch và Danh hiệu tương ứng.\\n\\nPhần thưởng của giải đấu sẽ được gửi trực tiếp về Hòm thư.\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Phần thưởng\",\"wrap\":true},\"cell\":{\"growX\":true,\"height\":30,\"space\":[30,0,30,0],\"row\":true}},{\"type\":\"scrollpane\",\"typeChild\":1,\"cell\":{\"height\":120,\"width\":720,\"row\":true,\"spaceTop\":50},\"childrens\":[{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":0},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":1},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":2},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":3},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":4},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":5},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":6},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":7},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}}]}]}', '[{\"i\":1},{\"i\":268},{\"i\":261},{\"i\":269},{\"i\":172,\"l\":1},{\"i\":274,\"l\":1},{\"i\":207,\"s\":[[9,250],[3,2500],[5,2500]],\"l\":1},{\"i\":211,\"s\":[[7,150],[15,200]],\"l\":1}]');
INSERT INTO `guide_topic` (`category_idx`, `idx`, `id`, `name`, `layout_json`, `rewards`) VALUES
(1, 10, 11, 'Lôi vực Sấm sét', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Lôi vực Sấm sét\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Nằm trên thượng nguồn Eldarah, nơi những dòng thác cổ đại đổ xuống từ vách núi linh giới, Lôi Vực Sấm Sét là vùng đất ngự trị của [#FFF600]Tinh linh Sấm Sét[reset] và được [#FFF600]Vệ thần Sấm Sét[reset] canh giữ\\n\\nĐây cũng là trường khốc liệt nơi các bộ lạc tranh đoạt tài nguyên và quyền kiểm soát vùng thượng nguồn\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":1,\"font\":2,\"fontSize\":22,\"text\":\"Tới gặp ông Tư tế Buraen tại Làng ánh sáng để tham gia\",\"wrap\":true},\"cell\":{\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Tư tế\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Ông Buraen\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/609\"},\"cell\":{\"padTop\":35,\"size\":[190,285],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Vùng Thượng nguồn linh thiêng này được bảo vệ bởi các thực thể Sấm sét cùng với Tinh linh Sấm sét và Vệ thầm Sấm sét, các thực thế tối cao ngự trị nơi đây sẽ tấn công bất kỳ kẻ xâm nhập nào\\n\\nTinh linh Sấm sét và Vệ thần Sấm sét sẽ xuất hiện lại mỗi 15 phút sau khi bị hạ gục, đánh bại các thực thể tối cao sẽ nhận được nhiều vật phẩm quý hiếm.\\nTỉ lệ xuất hiện Siêu quái và điểm Kinh nghiệm nhận được khi đánh quái tại nơi đây cũng sẽ cao hơnn\\n\\nÔng tư tế Buraen có thể hỗ trợ Thực hiện nghi thức Ấn linh để tăng 5% Tấn công, 15% HP,MP và 15% Giáp\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/764\"},\"cell\":{\"row\":true,\"size\":[139,167],\"expandX\":true,\"spaceTop\":35}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Golem Sấm sét\",\"wrap\":true},\"cell\":{\"row\":true,\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/763\"},\"cell\":{\"row\":true,\"size\":[139,167],\"expandX\":true,\"spaceTop\":35}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Golem Tia chớp\",\"wrap\":true},\"cell\":{\"row\":true,\"growX\":true}}]}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"spaceTop\":20,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/759\"},\"cell\":{\"padTop\":20,\"size\":[304,399],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Vệ thần Sấm sét\",\"wrap\":true},\"cell\":{\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"expandX\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/758\"},\"cell\":{\"padRight\":35,\"padTop\":254,\"size\":[183,165],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tinh linh Sấm sét\",\"wrap\":true},\"cell\":{\"padRight\":35,\"growX\":true}}]}]},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Mỗi ngày, mỗi người sẽ có 2 lượt tham gia miễn phí, dùng hết lượt miễn phí có thể sử dụng lệnh bài đấu trường mua tại của hàng Tư tế để tăng thêm lượt đi trong ngày (Tối đa thêm 2 lượt)\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/686\"},\"cell\":{\"row\":true,\"size\":[72,72],\"expandX\":true,\"spaceTop\":50}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Lệnh bài Đấu trường\",\"wrap\":true},\"cell\":{\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Mỗi lượt tham gia sẽ có thời gian 60 phút đồng thời người chơi tham gia sẽ nhận được 10 điểm hoạt động và 2 điểm cống hiến Bộ lạc, sau khi hết thời gian 60 phút sẽ tự động được đưa trở về nhà\\n\\nTại đây, toàn bộ người chơi sẽ ở trạng thái chiến đấu Bộ lạc, Đánh bại người chơi khác sẽ được 1 Điểm cống hiến Bộ lạc (Tối đa 5 điểm 1 trong 1 lượt) và 2 Điểm Hoạt động (Tối đa 10 điểm trong 1 lượt)\\n\\nNếu bị hạ gục sẽ tự động được phục hồi sau 5 giây nhưng nếu bị hạ gục quá 5 lần sẽ bị loại và được đưa trở về Làng\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Phần thưởng\",\"wrap\":true},\"cell\":{\"growX\":true,\"height\":30,\"space\":[30,0,30,0],\"row\":true}},{\"type\":\"scrollpane\",\"typeChild\":1,\"cell\":{\"height\":120,\"width\":720,\"row\":true,\"spaceTop\":50},\"childrens\":[{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":0},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":1},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":2},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":3},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":4},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":5},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":6},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}},{\"type\":\"slotitem\",\"typeChild\":1,\"properties\":{\"itemId\":7},\"cell\":{\"expandY\":true,\"size\":[104,104],\"pad\":[5,5,5,5]}}]}]}', '[{\"i\":1},{\"i\":274},{\"i\":269},{\"i\":268},{\"i\":261},{\"i\":145},{\"i\":369,\"s\":[[7,[25,50]],[9,[50,100]],[41,[50,100]],[55]]},{\"i\":172,\"l\":1}]'),
(1, 11, 12, 'Tế đàn Thiên tích', '{\"type\":\"table\",\"properties\":{},\"childrens\":[{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Tế đàn Thiên tích\",\"wrap\":true},\"cell\":{\"padTop\":-20,\"growX\":true,\"height\":30,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tế đàn Thiên Tích là thánh địa cổ xưa của Eldarah Từ rất lâu trước đây, vùng đất này là nơi ngự trị của Tinh linh Bầu trời và là trung tâm của các nghi lễ hiến tế cổ xưa\\n\\nTừ hàng trăm năm trước, khi Eldarah còn là một vùng đất hoang vu đầy thiên tai và hiểm họa, các bộ lạc đã tìm đến Tinh linh Bầu trời để cầu xin sự che chở. Theo khế ước, cứ mỗi đời thủ lĩnh bộ lạc sẽ phải chọn ra một người để dâng hiến tại Tế đàn Thiên Tích. Đổi lại, Tinh linh Bầu trời sẽ ban cho Eldarah mưa thuận gió hòa, mùa màng tốt tươi và sự bảo hộ khỏi những tai ương từ thiên nhiên\\n\\nĐến một ngày, Thủ lĩnh Gorun và con trai ông là Rinn đã đứng lên phản đối nghi thức hiến tế. Họ từ chối tiếp tục dâng mạng sống của người vô tội để đổi lấy sự che chở từ Tinh linh Bầu trời\\n\\nKhế ước bị phá vỡ\\n\\nCũng từ đó, cơn thịnh nộ của Tinh linh Bầu trời giáng xuống Eldarah. Sấm sét xé nát bầu trời, cuồng phong quét qua các bộ lạc và một cuộc chiến chưa từng có đã nổ ra.\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/762\"},\"cell\":{\"padTop\":35,\"size\":[400,330],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Ngày nay, Tế đàn Thiên Tích chỉ còn là một vùng đất u ám phủ đầy tàn tích cổ xưa. Sau khi khế ước bị phá vỡ, Tinh linh Bầu trời đã nổi cơn thịnh nộ và mang chiến tranh đến Eldarah. Dù bị phong ấn sau trận chiến năm ấy, ả vẫn chưa thực sự bị tiêu diệt\\n\\nCác Cận vệ Thiên Tích vẫn đang canh giữ và bảo vệ nơi đây, trung thành với chủ nhân của chúng qua hàng thế hệ\\n\\nKhông ai biết khi nào cơn thịnh nộ ấy sẽ quay trở lại... nhưng những đám mây đen chưa bao giờ hoàn toàn rời khỏi bầu trời nơi đây\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":1,\"font\":2,\"fontSize\":22,\"text\":\"Tới gặp ông Tư tế Buraen tại Làng ánh sáng để tham gia\\nMỗi ngày có 1 lượt miễn phí\",\"wrap\":true},\"cell\":{\"spaceTop\":10,\"row\":true,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":30,\"text\":\"[#FFF600]Tư tế\",\"wrap\":true},\"cell\":{\"padTop\":20,\"growX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Ông Buraen\",\"wrap\":true},\"cell\":{\"growX\":true,\"row\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/609\"},\"cell\":{\"padTop\":35,\"size\":[190,285],\"align\":1,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":10,\"font\":2,\"fontSize\":22,\"text\":\"Tế đàn Thiên tích được chia làm 7 khu vực bao quanh trung tâm tế đàn. Người chơi sẽ có 30 phút để đánh bại hết tất cả các Cận vệ Thiên tích, mỗi một vùng Tế đàn sẽ có 1 cận vệ canh giữ, khi vượt qua một vùng sẽ nhận được rương gỗ tương ứng\\n\\n      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - \\n\\n Vượt qua Tế đàn Cấm vệ (Map 1) sẽ nhận được Rương gỗ cấp 1 (Tại đây sẽ chạm trán Tinh linh Bầu trời lần 1)\\n\\n- Vượt qua Tế đàn Chiến vệ (Map 2) phần thưởng sẽ được nâng lên Rương gỗ cấp 2\\n\\n- Vượt qua Tế đàn Cận vệ (Map 3) phần thưởng sẽ được nâng lên Rương gỗ cấp 3 (Tại đây sẽ chạm trán Zyren)\\n\\n- Vượt qua Tế đàn Hộ vệ (Map 4) phần thưởng sẽ được nâng lên Rương gỗ cấp 4\\n\\n- Vượt qua Tế đàn Thiết vệ (Map 5) phần thưởng sẽ được nâng lên Rương gỗ cấp 5 (Tại đây sẽ chạm trán Vaelor)\\n\\n- Vượt qua Tế đàn Trấn vệ (Map 6) phần thưởng sẽ được nâng lên Rương gỗ cấp 6\\n\\n- Vượt qua Tế đàn Thần vệ (Map 7) phần thưởng sẽ được nâng lên Rương gỗ cấp 7 (Tại đây sẽ chạm trán Tinh linh Bầu trời lần 2)\\n\\n      - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - \\n\\nChiến binh chỉ có thể đi một mình, không thể đi cùng tổ đội nên nếu bị thoát ra ngoài vẫn có thể quay trở lại\\n Sau khi thời gian kết thúc, phần thưởng tương ứng sẽ được gửi về thư\\n\\nÔng tư tế Buraen có thể hỗ trợ Thực hiện nghi thức Ấn linh để tăng 15% Tấn công lên quái và 10% Hút HP,MP quái\",\"wrap\":true},\"cell\":{\"spaceTop\":20,\"row\":true,\"growX\":true}},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"row\":true,\"growX\":true,\"spaceTop\":50},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/769\"},\"cell\":{\"size\":[156,176],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/770\"},\"cell\":{\"padLeft\":50,\"size\":[165,165],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/768\"},\"cell\":{\"size\":[163,164],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Thiên tích Cấm vệ\",\"wrap\":true},\"cell\":{\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Thiên tích Chiến vệ\",\"wrap\":true},\"cell\":{\"padLeft\":50,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Thiên tích Cận vệ\",\"wrap\":true},\"cell\":{\"padLeft\":25,\"growX\":true,\"row\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"padTop\":35,\"padRight\":10,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/772\"},\"cell\":{\"padLeft\":-75,\"size\":[176,172],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/771\"},\"cell\":{\"padLeft\":-85,\"padtop\":0,\"size\":[165,157],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Thiên tích Hộ vệ\",\"wrap\":true},\"cell\":{\"padLeft\":-15,\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Thiên tích Thiết vệ\",\"wrap\":true},\"cell\":{\"padLeft\":-20,\"height\":40,\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"padTop\":35,\"padRight\":10,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/773\"},\"cell\":{\"padLeft\":-80,\"size\":[164,168],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/774\"},\"cell\":{\"padLeft\":-75,\"padtop\":4,\"size\":[149,164],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Thiên tích Trấn vệ\",\"wrap\":true},\"cell\":{\"padLeft\":-10,\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Thiên tích Thần vệ\",\"wrap\":true},\"cell\":{\"padLeft\":-20,\"height\":40,\"growX\":true}}]},{\"type\":\"table\",\"typeChild\":1,\"cell\":{\"growX\":true,\"padTop\":35,\"padRight\":10,\"row\":true},\"childrens\":[{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/778\"},\"cell\":{\"padLeft\":20,\"size\":[125,165],\"expandX\":true}},{\"type\":\"table\",\"typeChild\":1,\"properties\":{\"image\":\"icon/779\"},\"cell\":{\"padLeft\":20,\"size\":[130,165],\"expandX\":true,\"row\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\":{\"align\":2,\"font\":2,\"fontSize\":22,\"text\":\"Tinh linh Rồng Zyren\",\"wrap\":true},\"cell\":{\"padLeft\":-10,\"height\":40,\"growX\":true}},{\"type\":\"label\",\"typeChild\":1,\"properties\"