(158, 11, 0, 'Ma thuật Trường sinh', 'Nước ma thuật do Olivar chế tạo từ Hoa Mộc diên giúp tăng 50% HP trong vòng 5 phút', 'icon\\125', '0', 0, 'ui/203'),
(159, 11, 0, 'Ma thuật Tinh thần', 'Nước ma thuật do Olivar chế tạo từ Hoa Lam tinh giúp tăng 50% MP trong vòng 5 phút', 'icon\\127', '0', 0, 'ui/203'),
(160, 11, 0, 'Ma thuật Bạo kích', 'Nước ma thuật do Olivar chế tạo từ Hoa Tử nguyệt giúp tăng 20% Tấn công trong vòng 5 phút', 'icon\\126', '0', 0, 'ui/203'),
(161, 11, 0, 'Ma thuật Tốc độ', 'Nước ma thuật do Olivar chế tạo từ Hoa Mộng huyền giúp tăng 20% Tốc độ di chuyển và 20% Né tránh trong vòng 5 phút', 'icon\\129', '0', 0, 'ui/203'),
(162, 11, 0, 'Ma thuật Tập trung', 'Nước ma thuật do Olivar chế tạo từ Hoa Huyết lan giúp tăng 50% Xuyên giáp và 20% Chính xác trong vòng 5 phút', 'icon\\124', '0', 0, 'ui/203'),
(163, 11, 0, 'Ma thuật Bất khuất', 'Nước ma thuật do Olivar chế tạo từ Hoa Hỏa diệp giúp tăng 50% Giáp trong vòng 5 phút', 'icon\\128', '0', 0, 'ui/203'),
(164, 7, 0, 'Cần câu', 'Cần câu gỗ buộc dây thừng thô sơ sử dụng để câu cá', 'icon\\121', '0', 0, 'ui/203'),
(165, 34, 0, 'Khiên vỏ sò', 'Tấm vỏ sò cổ đại được rèn cứng thành chiếc khiên, giúp triệt tiêu 20% Sát thương nhận vào.  Khi nhận đủ 1,000,000 sát thương Khiên vỏ sò sẽ bị vỡ và hết hiệu lực', 'icon\\153', '0', 0, 'ui/203'),
(166, 99, 0, 'Bùa tẩy điểm', 'Tấm bùa chứa năng lượng tinh khiết, dùng để tái lập cân bằng sức mạnh. Khi sử dụng sẽ đặt lại toàn bộ kỹ năng và chỉ số cơ bản đồng thời hoàn trả lại toàn bộ Điểm tiềm năng đã sử dụng để nâng cấp kỹ năng', 'icon\\173', '0', 0, 'ui/203'),
(167, 11, 0, 'Bùa hộ giáp', 'Tấm bùa phòng thủ được bảo hộ bời thần linh. Khi sử dụng, trong vòng 1 giờ sẽ không thể bị người chơi khác tấn công đồng thời cũng không thể tấn công người khác', 'icon\\172', '0', 0, 'ui/202'),
(168, 99, 0, 'Cờ lệnh Bộ lạc', 'Lá cờ nhỏ mang biểu tượng của bộ lạc được người thủ lĩnh dùng để thành lập một bộ lạc mới.', 'icon\\152', '0', 0, 'ui/205'),
(169, 17, 0, 'Bùa bảo hiểm Cấp 1', 'Lá bùa bảo vệ cơ bản dùng khi nâng cấp trang bị dưới 5 sao giúp bảo vệ trang bị khỏi bị hạ cấp sao khi nâng cấp thất bại', 'icon\\175', '0', 0, 'ui/203'),
(170, 17, 0, 'Bùa bảo hiểm Cấp 2', 'Lá bùa bảo vệ cấp cao dùng khi nâng cấp mọi trang bị giúp bảo vệ trang bị khỏi bị hạ cấp sao khi nâng cấp thất bại', 'icon\\174', '0', 0, 'ui/204'),
(171, 99, 0, 'Cỏ may mắn', 'Loại cỏ mang biểu tượng của may mắn được dùng khi khảm, nâng cấp hoặc chế tạo vũ khí và trang bị giúp tăng tỉ lệ thành', 'icon\\150', '0', 0, 'ui/203'),
(172, 18, 0, 'Rương Hoạt động', 'Rương gỗ được khảm hoa văn bộ lạc, phần thưởng cho hoạt động của người chơi trong ngày. Cần 50 điểm hoạt động để mở rương', 'icon\\146', '0', 0, 'ui/202'),
(173, 18, 0, 'Rương Phụ kiện', 'Rương gỗ mang biểu tượng linh lực nguyên thủy, chứa nhiều các phụ kiện hỗ trợ chiến đấu. Cần 50 điểm hoạt động để mở rương', 'icon\\145', '0', 0, 'ui/202'),
(174, 18, 0, 'Rương Chiến binh', 'Rương gỗ mang biểu tượng của những chiến binh, chứa nhiều phần thưởng quý giá bên trong. Cần 100 điểm hoạt động để mở rương', 'icon\\147', '0', 0, 'ui/203'),
(175, 18, 0, 'Rương Thợ săn', 'Rương gỗ mang biểu tượng của những thợ săn lão luyện, chứa nhiều phần thưởng quý giá bên trong. Cần 200 điểm hoạt động để mở rương', 'icon\\148', '0', 0, 'ui/204'),
(176, 18, 0, 'Rương Thủ lĩnh', 'Rương gỗ mang biểu tượng tối cao của người thủ lĩnh, chứa nhiều phần thưởng quý giá bên trong. Cần 350 điểm hoạt động để mở rương', 'icon\\149', '0', 0, 'ui/205'),
(177, 33, 0, 'Mảnh Rìu Bất hoại', 'Mảnh phôi khoáng thạch Đá Bất hoại mang sức mạnh nguyên thủy dùng để chế tạo Rìu Bất hoại', 'icon\\222', '0', 0, 'ui/204'),
(178, 33, 0, 'Mảnh Rìu Lục linh', 'Mảnh phôi khoáng thạch Đá Lục linh ẩn giấu sức mạnh cổ xưa dùng để chế tạo Rìu Lục linh', 'icon\\223', '0', 0, 'ui/205'),
(179, 33, 0, 'Mảnh Giáo Bất hoại', 'Mảnh phôi khoáng thạch Đá Bất hoại ẩn giấu sức mạnh cổ xưa dùng để chế tạo Giáo Bất hoại', 'icon\\216', '0', 0, 'ui/204'),
(180, 33, 0, 'Mảnh Giáo Lục linh', 'Mảnh phôi khoáng thạch Đá Lục linh ẩn giấu sức mạnh cổ xưa dùng để chế tạo Giáo Lục linh', 'icon\\217', '0', 0, 'ui/205'),
(181, 33, 0, 'Mảnh Roi da Bất hoại', 'Mảnh phôi khoáng thạch Đá Bất hoại ẩn giấu sức mạnh cổ xưa dùng để chế tạo Roi da Bất hoại', 'icon\\214', '0', 0, 'ui/204'),
(182, 33, 0, 'Mảnh Roi da Lục linh', 'Mảnh phôi khoáng thạch Đá Lục linh ẩn giấu sức mạnh cổ xưa dùng để chế tạo Roi da Lục linh', 'icon\\215', '0', 0, 'ui/205'),
(183, 33, 0, 'Mảnh Cung tên Bất hoại', 'Mảnh phôi khoáng thạch Đá Bất hoại ẩn giấu sức mạnh cổ xưa dùng để chế tạo Cung tên Bất hoại', 'icon\\218', '0', 0, 'ui/204'),
(184, 33, 0, 'Mảnh Cung tên Lục linh', 'Mảnh phôi khoáng thạch Đá Lục linh ẩn giấu sức mạnh cổ xưa dùng để chế tạo Cung tên Lục linh', 'icon\\219', '0', 0, 'ui/205'),
(185, 33, 0, 'Mảnh Ná thun Bất hoại', 'Mảnh phôi khoáng thạch Đá Bất hoại ẩn giấu sức mạnh cổ xưa dùng để chế tạo Ná thun Bất hoại', 'icon\\220', '0', 0, 'ui/204'),
(186, 33, 0, 'Mảnh Ná thun Lục linh', 'Mảnh phôi khoáng thạch Đá Lục linh ẩn giấu sức mạnh cổ xưa dùng để chế tạo Ná thun Lục linh', 'icon\\221', '0', 0, 'ui/205'),
(187, 19, 0, 'Tinh linh Rừng xanh', 'Tinh Linh Rừng Xanh là thực thể sinh ra từ linh khí cổ xưa ngự trị phía nam khu rừng Sayari, vị thần tối cao cai quản khu rừng linh thiêng này', 'icon\\285', '0', 0, 'ui/204'),
(188, 19, 0, 'Tinh linh Đầm lầy', 'Tinh linh Đầm lầy là linh hồn cổ xưa vùng đầm lầy Avenna, vị thần bảo hộ cho ma thuật tại vùng đất này', 'icon\\286', '0', 0, 'ui/204'),
(189, 19, 0, 'Tinh linh Biển cả', 'Tinh linh Biển cả là linh hồn của vùng biển Velmora, được dân làng nơi đây tôn thờ như vị thần bảo hộ đại dương mang đến phước lành', 'icon\\288', '0', 0, 'ui/204'),
(190, 19, 0, 'Tinh linh Phong thạch', 'Tinh linh Phong thạch là linh hồn của gió trời và linh thạch vùng Darguun, vị thần trấn giữ trật tự tự nhiên của vùng đất này', 'icon\\290', '0', 0, 'ui/204'),
(191, 19, 0, 'Tinh linh Băng giá', 'Tinh linh Băng giá là thực thể cổ xưa sinh ra từ linh khí hàn băng vùng Frearh, vị thần cai quản sự tĩnh lặng và thanh khiết vùng núi tuyết', 'icon\\287', '0', 0, 'ui/205'),
(192, 19, 0, 'Tinh linh Bầu trời', 'Tinh linh Bầu trời là thực thể tối thượng sinh ra từ thiên không vô tận, vị thần hộ mệnh của bầu trời và ánh sáng vùng Eldarah tuy nhiên không có gì là miễn phí', 'icon\\289', '0', 0, 'ui/205'),
(193, 28, 0, 'Hoa Huyết lan', 'Hoa ma thuật đỏ mọc ở vùng đầm lầy Avenna dùng để chế tạo thuốc Ma thuật Tập trung', 'icon\\458', '0', 0, 'ui/202'),
(194, 28, 0, 'Hoa Mộc diên', 'Hoa ma thuật xanh lục mọc ở vùng đầm lầy Avenna dùng để chế tạo thuốc Ma thuật Trường sinh', 'icon\\457', '0', 0, 'ui/202'),
(195, 28, 0, 'Hoa Tử nguyệt', 'Hoa ma thuật tím mọc ở vùng đầm lầy Avenna dùng để chế tạo thuốc Ma thuật Bạo kích', 'icon\\459', '0', 0, 'ui/202'),
(196, 28, 0, 'Hoa Lam tinh', 'Hoa ma thuật xanh lam mọc ở vùng đầm lầy Avenna dùng để chế tạo thuốc Ma thuật Sinh lực', 'icon\\460', '0', 0, 'ui/202'),
(197, 28, 0, 'Hoa Hỏa diệp', 'Hoa ma thuật cam mọc ở vùng đầm lầy Avenna dùng để chế tạo thuốc Ma thuật Bất khuất', 'icon\\456', '0', 0, 'ui/202'),
(198, 28, 0, 'Hoa Mộng huyền', 'Hoa ma thuật hồng mọc ở vùng đầm lầy Avenna dùng để chế tạo thuốc Ma thuật Tốc độ', 'icon\\455', '0', 0, 'ui/202'),
(199, 19, 0, 'Ariyah', 'Ariyah là trinh sát của bộ lạc Eldarah, cô được huấn luyện từ nhỏ. Sở hữu ánh mắt sắc bén và là người lặng lẽ quan sát bảo vệ Eldarah khỏi những mối đe dọa', 'icon\\443', '0', 0, 'ui/203'),
(200, 19, 0, 'Sariah', 'Sinh ra trên cao nguyên Darguun. Sariah là em gái của Bruk, Lớn lên giữa gió đá khắc nghiệt, cô mang trong mình sự cứng cáp và ý chí của một chiến binh', 'icon\\442', '0', 0, 'ui/204'),
(201, 99, 0, 'Bình nước phép', 'Bình nước tinh khiết dùng để làm nguyên liệu chế tạo ra các loại Nước ma thuật', 'icon\\224', '0', 0, 'ui/202'),
