(234, 27, 0, 'Táo vàng', 'Quả táo vàng óng ánh hiếm có giúp hồi phục lại 100% HP và Mp khi sử dụng', 'icon\\451', '0', 0, 'ui/204'),
(235, 23, 0, 'Heo con', 'Heo rừng con giống đã được thuần hóa hoàn toàn, có thể nuôi tại nhà', 'icon\\454', '0', 0, 'ui/203'),
(236, 19, 0, 'Rinna', 'Rinna lớn lên giữa khu rừng Sayari nơi thú dữ rình rập và linh khí thiên nhiên lan tỏa trong từng tán lá. Từ nhỏ, cô đã theo chân những thợ săn lão luyện băng qua rừng sâu, đọc dấu chân thú và sinh tồn giữa hoang dã', 'icon\\444', '0', 0, 'ui/204'),
(237, 19, 0, 'Lạc Long Quân', 'Lạc Long Quân là thủy thần truyền thuyết Văn Lang, hiện thân của rồng thiêng, cai quản sông biển và linh khí đại dương, mang huyết mạch Long tộc và quyền năng bảo hộ muôn dân', 'icon\\445', '0', 0, 'ui/205'),
(238, 99, 0, 'Cỏ hồi sinh', 'Thảo dược mang nguốn sinh lực mạnh mẽ dùng để đánh thức cơ thể khi rơi vào trạng thái kiệt sức', 'icon\\466', '0', 0, 'ui/202'),
(239, 99, 0, 'Tù và', 'Chiếc tù và được làm sừng động vật. Khi thổi lên, âm thanh vang vọng khắp núi rừng truyền đi thông điệp của người sử dụng đến toàn bộ chiến binh trên Kênh thế giới', 'icon\\572', '0', 15, 'ui/202'),
(240, 19, 0, 'Tinh linh Ánh lửa', 'Tinh linh Ánh lửa là linh hồn của hỏa vũ nguyên thủy, vị thần bảo đại diện hỏa thuật và sức mạnh tái sinh tại vùng dung nham thánh địa', 'icon\\462', '0', 0, 'ui/204'),
(241, 19, 0, 'Tinh linh Sấm sét', 'Tinh linh Sấm sét là thực thể cổ xưa sinh ra từ phong lôi nguyên thủy, vị thần đại diện lôi thuật và sức mạnh hủy diệt của vùng trời bão tố', 'icon\\461', '0', 0, 'ui/204'),
(242, 19, 0, 'Âu Cơ', 'Âu Cơ là mẫu thần cổ đại của Văn Lang, hiện thân của tiên linh núi rừng, cội nguồn của dòng giống Lạc Hồng, biểu tượng cho sinh mệnh, khai sinh và sự bảo hộ thiêng liêng của đất trời', 'icon\\463', '0', 0, 'ui/205'),
(243, 32, 0, 'Biểu tượng Thần rừng', 'Biểu tượng linh thiêng, là dấu hiệu nhận diện của bộ lạc. Giúp kết nối bộ lạc con người với thế giới linh hồn, tự nhiên và thần thú nguyên thủy', 'icon\\566', '0', 0, 'ui/204'),
(244, 32, 0, 'Biểu tượng Linh ngưu', 'Biểu tượng linh thiêng, là dấu hiệu nhận diện của bộ lạc. Giúp kết nối bộ lạc con người với thế giới linh hồn, tự nhiên và thần thú nguyên thủy', 'icon\\567', '0', 0, 'ui/204'),
(245, 32, 0, 'Biểu tượng Nanh lửa', 'Biểu tượng linh thiêng, là dấu hiệu nhận diện của bộ lạc. Giúp kết nối bộ lạc con người với thế giới linh hồn, tự nhiên và thần thú nguyên thủy', 'icon\\568', '0', 0, 'ui/204'),
(246, 32, 0, 'Biểu tượng Ưng vũ', 'Biểu tượng linh thiêng, là dấu hiệu nhận diện của bộ lạc. Giúp kết nối bộ lạc con người với thế giới linh hồn, tự nhiên và thần thú nguyên thủy', 'icon\\569', '0', 0, 'ui/204'),
(247, 32, 0, 'Biểu tượng Ma cốt', 'Biểu tượng linh thiêng, là dấu hiệu nhận diện của bộ lạc. Giúp kết nối bộ lạc con người với thế giới linh hồn, tự nhiên và thần thú nguyên thủy', 'icon\\570', '0', 0, 'ui/204'),
(248, 32, 0, 'Biểu tượng Lang diện', 'Biểu tượng linh thiêng, là dấu hiệu nhận diện của bộ lạc. Giúp kết nối bộ lạc con người với thế giới linh hồn, tự nhiên và thần thú nguyên thủy', 'icon\\571', '0', 0, 'ui/204'),
(249, 32, 0, 'Biểu tượng Cờ lệnh', 'Biểu tượng linh thiêng, là dấu hiệu nhận diện của bộ lạc. Giúp kết nối bộ lạc con người với thế giới linh hồn, tự nhiên và thần thú nguyên thủy', 'icon\\152', '0', 0, 'ui/201'),
(250, 36, 0, 'Mặt nạ Rừng xanh', 'Mặt nạ Rừng xanh', 'icon\\576', '0', 0, 'ui/204'),
(251, 99, 0, 'Cá Vây xanh', 'Thu được từ hoạt động câu cá. Có thể dùng để trao đổi, buôn bán hoặc phục vụ một số nhiệm vụ đặc biệt', 'icon\\577', '0', 0, 'ui/201'),
(252, 36, 0, 'Mặt nạ Nanh hổ', 'Mặt nạ Nanh hổ', 'icon\\573', '0', 0, 'ui/205'),
(253, 99, 0, 'Cá Diêu hồng', 'Thu được từ hoạt động câu cá. Có thể dùng để trao đổi, buôn bán hoặc phục vụ một số nhiệm vụ đặc biệt', 'icon\\575', '0', 0, 'ui/202'),
(254, 99, 0, 'Cá Diễm Hỏa', 'Thu được từ hoạt động câu cá. Có thể dùng để trao đổi, buôn bán hoặc phục vụ một số nhiệm vụ đặc biệt', 'icon\\574', '0', 0, 'ui/203'),
(255, 99, 0, 'Đá linh thạch', 'Khoáng thạch cổ được kết tinh qua hàng ngàn năm chứa ma thuật có khả năng liên kết các phôi vũ khí thành một khối hoàn chỉnh', 'icon\\251', '0', 0, 'ui/205'),
(256, 20, 0, 'Danh hiệu Tinh anh', 'Danh hiệu Tinh anh', 'icon\\544', '0', 0, 'ui/203'),
(257, 20, 0, 'Danh hiệu Cần thủ', 'Danh hiệu Cần thủ', 'icon\\545', '0', 0, 'ui/203'),
(258, 20, 0, 'Danh hiệu Siêng năng', 'Danh hiệu Siêng năng', 'icon\\543', '0', 0, 'ui/203'),
(259, 20, 0, 'Danh hiệu Phú hào', 'Danh hiệu Phú hào', 'icon\\542', '0', 0, 'ui/205'),
(260, 19, 0, 'Tinh Linh Thần mộc', 'Tinh linh Thần Mộc là tà thần mang linh hồn bóng tối sở hữu sức mạnh Linh mộc, nó có thể thao túng thực thể Hắc linh đáng sợ chống lại mọi kẻ xâm nhập', 'icon\\489', '0', 0, 'ui/203'),
(261, 99, 0, 'Ấn thủ lĩnh', 'Chiến lợi phẩm từ những trận chiến khốc liệt. Chiến binh đã trải qua nhiều trận chiến thu thập những mảnh ấn để đổi lấy trang bị thủ lĩnh tại Tư Tế Buraen', 'icon\\583', '0', 0, 'ui/205'),
(262, 34, 0, 'Nanh Hổ răng kiếm', 'Răng nanh của những con Hổ Răng Kiếm to lớn trong khu rừng Sayari vẫn còn lưu lại sát khí của cuộc đi săn trong rừng sâu. Đòn đánh hoặc kỹ năng đầu tiên đánh lên mục tiêu chắc chắn sẽ chí mạng và gây thêm 20% sát thương chí mạng. Khi kích hoạt 500 lần Nanh Hổ răng kiếm sẽ bị vỡ và hết hiệu lực', 'icon\\590', '0', 0, 'ui/203'),
(263, 34, 0, 'Bùa linh mộc', 'Ấn gỗ khắc biểu tượng con mắt cổ xưa của rừng Sayari, mang theo linh khí của đại ngàn che chở cho chiến binh trong khoảnh khắc sinh tử. Sau khi hồi sinh sẽ được bất tử trong 3 giây và tăng 10% Khuếch đại Tấn công trong 15 giây. Khi kich hoạt 100 lần Bùa linh mộc sẽ bị vỡ và hết hiệu lực', 'icon\\588', '0', 0, 'ui/203'),
(264, 34, 0, 'Mắt bão Darguun', 'Vật tổ của những chiến binh cao nguyên, người Darguun tin rằng nó chứa sức mạnh của cơn gió. Mỗi khi sử dụng kỹ năng, tăng 2000 né tránh và 20% tốc độ di chuyển trong 5 giây. Khi kich hoạt 500 lần Mắt bão sẽ bị vỡ và hết hiệu lực', 'icon\\591', '0', 0, 'ui/203'),
(265, 6, 0, 'Giày da cũ', 'Một chiếc giày mục nát, không rõ bị thất lạc từ bao giờ. Thỉnh thoảng người câu cá lại kéo lên thứ này, có lẽ nó đã trôi dạt trong nước từ rất lâu, Đôi khi nó cũng sở hữu một vài chỉ số mạnh mẽ', 'icon\\587', '0', 0, 'ui/200'),
(266, 99, 0, 'Xương thú', 'Những mảnh xương còn sót lại từ xác thú hoang, chúng vẫn đủ cứng để chế tác thành những vũ khí đơn giản phục vụ cho chiến đấu và săn bắt.', 'icon\\586', '0', 0, 'ui/200'),
(267, 99, 0, 'Đá thô sơ', 'Những khối đá thô được nhặt từ sườn núi và lòng suối, chúng có thể được chế tạo thành khí đơn giản cho các tân binh phục vụ cho chiến đấu và săn bắt.', 'icon\\589', '0', 0, 'ui/200'),
(268, 18, 0, 'Túi linh thạch', 'Bên trong chứa 1 Mảnh linh thạch vũ khí Bất hoại hoặc Lục linh có thể chế tạo thành những món thần binh mạnh mẽ.', 'icon\\584', '0', 0, 'ui/205'),
(269, 18, 0, 'Túi đá nguyên tố', 'Bên trong chứa đá nguyên tố ngẫu nhiên, mỗi viên mang theo một thuộc tính có khể khảm vào trang bị để tăng sức chiến đấu', 'icon\\585', '0', 0, 'ui/203'),
(270, 19, 0, 'Setdan', 'Setdan là thợ săn dày dạn kinh nghiệm trong bộ tộc Sayari. Lớn lên giữa khu rừng rậm rạp và hoang dã, anh sở hữu bản năng săn mồi vô cùng sắc bén', 'icon\\592', '0', 0, 'ui/203'),
(271, 99, 0, 'Xương cá', 'Phần xương còn sót lại của một con cá đã bị ăn sạch, không còn giá trị sử dụng', 'icon\\593', '0', 0, 'ui/200'),
(272, 11, 0, 'Tảo bẹ', 'Tảo bẹ xanh thường mọc thành từng cụm dọc theo những bãi đá ẩm ven sông và vùng nước nông ven biển của Eldarah, Khi sử dụng tăng 750 Chí mạng trong vòng 5 phút', 'icon\\594', '0', 0, 'ui/203'),
(273, 19, 0, 'Thủ lĩnh Gorun', 'Thủ lĩnh của bộ lạc Eldarah, là chiến binh đã trải qua vô số trận chiến khốc liệt. Lớn lên giữa vùng đất hoang dã và khắc nghiệt, ông đã tôi luyện sức mạnh, ý chí và kinh nghiệm để dẫn dắt bộ lạc vượt qua những năm tháng khó khăn', 'icon\\654', '0', 0, 'ui/205'),
(274, 99, 0, 'Đá khởi nguyên', 'Khối đá cổ xưa mang trong mình hai nguồn linh lực Nhật Nguyệt đối lập có thể tinh luyện thành Đá Mặt Trời hoặc Đá Mặt Trăng', 'icon\\610', '0', 0, 'ui/202'),
(275, 11, 0, 'Nấm hương', 'Loại nấm mọc trong rừng ẩm Sayari, mang hương thơm đặc trưng, khi sử dụng Hồi lại 1% HP và MP mỗi 5 giây trong vòng 30 phút', 'icon\\600', '0', 0, 'ui/203'),
(276, 20, 0, 'Danh hiệu Thương gia', 'Danh hiệu Thương gia', 'icon\\652', '0', 0, 'ui/203'),
(277, 20, 0, 'Danh hiệu Phù thủy', 'Danh hiệu Phù thủy', 'icon\\653', '0', 0, 'ui/203'),
(278, 34, 0, 'Tim băng', 'Tinh thể lạnh giá kết tinh từ linh khí hàn băng cổ đại, tỏa ra hơi lạnh thấu xương chứa sức mạnh băng giá khiến đòn đánh có thêm tỉ lệ đóng băng mục tiêu. Khi kích hoạt 500 lần Tim băng sẽ bị vỡ và hết hiệu lực', 'icon\\684', '0', 0, 'ui/203'),
(279, 34, 0, 'Nhẫn u mộc', 'Được bện từ rễ ma thuật của vùng đầm lầy Avenna khiến đòn đánh có thêm tỉ lệ triệu hồi rễ cây và trói buộc kẻ địch. Khi kích hoạt 500 lần Nhẫn u mộc sẽ bị vỡ và hết hiệu lực', 'icon\\685', '0', 0, 'ui/203'),
(280, 99, 0, 'Vỏ ốc anh vũ', 'Vỏ ốc anh vũ cổ xưa có niên đại hàng triệu năm thường trôi dạt vào bờ biển theo những cơn sóng và được những con Ốc mượn hồn sử dụng để làm nhà', 'icon\\647', '0', 0, 'ui/203'),
(281, 35, 0, 'Kinh nghiệm', 'Điểm kinh nghiệm', 'icon\\675', '0', 0, 'ui/203'),
(282, 20, 0, 'Danh hiệu Chuyên cần', 'Danh hiệu Chuyên cần', 'icon\\658', '0', 0, 'ui/203'),
(283, 36, 0, 'Mặt nạ Cổ Thần', 'Mặt nạ Cổ Thần', 'icon\\659', '0', 0, 'ui/204'),
(284, 36, 0, 'Mặt nạ Thợ săn', 'Mặt nạ Thợ săn', 'icon\\660', '0', 0, 'ui/205'),
(285, 36, 0, 'Mặt nạ Chiến binh', 'Mặt nạ Chiến binh', 'icon\\661', '0', 0, 'ui/204'),
(286, 36, 0, 'Mặt nạ Thủy vực', 'Mặt nạ Thủy vực', 'icon\\662', '0', 0, 'ui/204'),
(287, 36, 0, 'Mặt nạ Thủ lĩnh', 'Mặt nạ Thủ lĩnh', 'icon\\663', '0', 0, 'ui/205'),
(288, 18, 0, 'Quả Linh Mộc', 'Tinh hoa kết tụ từ sâu trong lòng Rừng Linh Mộc. Sử dụng để nhận ngẫu nhiên nhiều phần thưởng giá trị. Cần 20 điểm hoạt động để mở quà', 'icon\\682', '0', 0, 'ui/203'),
(289, 37, 0, 'Hươu Linh mộc', 'Khi rễ Linh Mộc lan xuống lòng đất và tích tụ linh khí qua hàng trăm năm, chúng kết tinh thành những sinh linh mang hình hài nửa thú, nửa cây. Hươu Linh mộc là một trong những thực thể như vậy.', 'icon\\678', '0', 0, 'ui/203'),
(290, 37, 0, 'Moara', 'Sinh ra trên Thảo nguyên Eldarah, Moara là linh thú đặc biệt. Nhờ khả năng cảm nhận những biến động nhỏ nhất của linh khí và tự nhiên, chúng thường được sử dụng để dự báo các hiện tượng bất thường như bão, động đất hay sự xáo trộn năng lượng.', 'icon\\676', '0', 0, 'ui/203'),
(291, 37, 0, 'Tiểu Tinh linh Cáo', 'Ẩn mình trong các khu rừng và làng mạc Eldarah, Tiểu Tinh linh Cáo là loài sinh vật nhỏ bé nhưng cực kỳ nhanh nhẹn và ranh mãnh. Chúng thường lặng lẽ tiếp cận mục tiêu, nhanh tay cuỗm đi một phần vàng rồi biến mất chỉ trong chớp mắt', 'icon\\677', '0', 0, 'ui/204'),
(292, 18, 0, 'Thỏi vàng', 'Một khối kim loại vàng quý hiếm được tinh luyện và đúc thành thỏi. Sử dụng sẽ nhận được 1.000.000 vàng. Một ngày chỉ có thể sử dụng tối đa 30 Thỏi vàng', 'icon\\683', '0', 0, 'ui/205'),
(293, 99, 0, 'Lệnh bài Đấu trường', 'Lệnh bài của các chức sắc Bộ lạc Eldarah trao lại cho những Chiến binh. Sử dụng để nhận 1 lượt tham gia Lôi vực Sấm sét', 'icon\\686', '0', 0, 'ui/202'),
(294, 99, 0, 'Túi đựng Táo', 'Chiếc túi vải thô bên trong lót một lớp lá khô giúp giữ cho những Quả táo luôn tươi lâu hơn. Có thể mang theo 99 Quả táo trong hành trang', 'icon\\715', '0', 0, 'ui/204'),
(295, 38, 0, 'Trái tim đại dương', 'Sinh ra từ nơi những dòng chảy hội tụ mang theo hơi thở của đại dương. Khi ở gần nước sẽ tăng 100 tốc độ di chuyển và 5% Tấn công', 'icon\\714', '0', 0, 'ui/203'),
(296, 17, 0, 'Ngọc trai đen', 'Viên ngọc trai đen hình thành từ những tầng biển sâu tăm tối của Velmora. Sử dụng vật phẩm thay bảo hiểm khi nâng cấp trang bị cấp 3 trở lên, nếu thành công trang bị sẽ tăng 12% chỉ số thay vì 4%. Nhưng nếu thất bại thì trang bị sẽ bị quay trở về cấp 1', 'icon\\712', '0', 0, 'ui/205'),
(297, 11, 0, 'Túi sữa dê', 'Túi sữa tươi được người Darguun thu hoạch từ những con Linh dương sống trên cao nguyên. Khi sử dụng sẽ loại bỏ tất cả các hiệu ứng bất lợi trên bản thân đồng thời miễn nhiễm các hiệu ứng đó trong 30 giây', 'icon\\716', '0', 0, 'ui/203');
INSERT INTO `item_template` (`id`, `type_id`, `class_id`, `name`, `description`, `icon_path`, `preview_image_path`, `required_level`, `emblem_path`) VALUES
(298, 18, 0, 'Túi Khởi nguyên', 'Bên trong túi có chứa ngẫu nhiên 1000-2000 Đá khởi nguyên, nguồn tài nguyên thiết yếu dùng để luyện thành Đá cường hóa giúp tăng sức mạnh trang bị. Mỗi ngày chỉ được sử dụng tối đa 10 Túi', 'icon\\720', '0', 0, 'ui/203'),
(299, 11, 0, 'Thuốc trí tuệ II', 'Dược phẩm được Nimora điều chế giúp tăng 100% Kinh nghiệm khi đánh quái trong vòng 30 phút', 'icon\\728', '0', 0, 'ui/204'),
(300, 11, 0, 'Thuốc Sức mạnh II', 'Dược phẩm được Nimora điều chế giúp tăng 70% Sức tấn công lên quái trong vòng 30 phút', 'icon\\726', '0', 0, 'ui/204'),
(301, 11, 0, 'Thuốc Cứng cáp II', 'Dược phẩm được Nimora điều chế giúp giảm 70% Sát thương nhận vào từ quái trong vòng 30 phút', 'icon\\727', '0', 0, 'ui/204'),
(303, 19, 0, 'Tarae', 'Tarae là người Làng ánh sáng, cô sống một mình ở Ngoại ô làng. Người trong làng vẫn biết đến cô. Thỉnh thoảng, Tarae sẽ xuất hiện với những vật phẩm săn bắn từ vùng hoang dã để trao đổi với người dân trong làng đổi lấy lương thực rồi lại rời đi', 'icon\\732', '0', 0, 'ui/204'),
(304, 36, 0, 'Mặt nạ Minh mộc', 'Mặt nạ Minh mộc', 'icon\\736', '0', 0, 'ui/203'),
(305, 36, 0, 'Mặt nạ Đại dương', 'Mặt nạ Đại dương', 'icon\\734', '0', 0, 'ui/204'),
(306, 36, 0, 'Mặt nạ Quỷ cốt', 'Mặt nạ Quỷ cốt', 'icon\\735', '0', 0, 'ui/204'),
(307, 99, 0, 'Đồng xu may mắn', 'Đồng xu cổ đại được lưu truyền từ thời kỳ sơ khai của Eldarah, người ta tin rằng mỗi đồng xu đều chứa một phần linh khí còn sót lại từ thời đại cổ xưa và sử dụng nó cho hoạt động Vòng Quay May Mắn', 'icon\\737', '0', 0, 'ui/203'),
(308, 99, 0, 'Thẻ đổi tên', 'Cho phép người sở hữu thay đổi tên nhân vật của mình trước sự chứng kiến của thần linh', 'icon\\739', '0', 0, 'ui/205'),
(309, 99, 0, 'Vé nhiệm vụ', 'Tấm vé mang ấn của Tư tế dùng để xin thay đổi Nhiệm vụ Hằng ngày hoặc nhận thêm thử thách mới từ Thần linh', 'icon\\740', '0', 0, 'ui/203'),
(310, 17, 0, 'Bùa bảo hiểm Tinh linh', 'Lá bùa bảo vệ của Tinh linh dùng khi nâng cấp mọi trang bị giúp bảo vệ trang bị khỏi bị hạ cấp sao đồng thời giữ lại tài nguyên khi nâng cấp thất bại', 'icon\\751', '0', 0, 'ui/205'),
(311, 18, 0, 'Rương gỗ cấp 1', 'Phần thưởng của những chiến binh đã chiến đấu tại Tế đàn Eldarah, Bên trong có nhiều vật phẩm quý hiếm. Cần 25 điểm hoạt động để mở rương', 'icon\\733', '0', 0, 'ui/200'),
(312, 18, 0, 'Rương gỗ cấp 2', 'Phần thưởng của những chiến binh đã chiến đấu tại Tế đàn Eldarah, Bên trong có nhiều vật phẩm quý hiếm. Cần 25 điểm hoạt động để mở rương', 'icon\\733', '0', 0, 'ui/200'),
(313, 18, 0, 'Rương gỗ cấp 3', 'Phần thưởng của những chiến binh đã chiến đấu tại Tế đàn Eldarah, Bên trong có nhiều vật phẩm quý hiếm. Cần 25 điểm hoạt động để mở rương', 'icon\\733', '0', 0, 'ui/201'),
(314, 18, 0, 'Rương gỗ cấp 4', 'Phần thưởng của những chiến binh đã chiến đấu tại Tế đàn Eldarah, Bên trong có nhiều vật phẩm quý hiếm. Cần 25 điểm hoạt động để mở rương', 'icon\\733', '0', 0, 'ui/202'),
(315, 18, 0, 'Rương gỗ cấp 5', 'Phần thưởng của những chiến binh đã chiến đấu tại Tế đàn Eldarah, Bên trong có nhiều vật phẩm quý hiếm. Cần 25 điểm hoạt động để mở rương', 'icon\\733', '0', 0, 'ui/203'),
(316, 18, 0, 'Rương gỗ cấp 6', 'Phần thưởng của những chiến binh đã chiến đấu tại Tế đàn Eldarah, Bên trong có nhiều vật phẩm quý hiếm. Cần 25 điểm hoạt động để mở rương', 'icon\\733', '0', 0, 'ui/204'),
(317, 18, 0, 'Rương gỗ cấp 7', 'Phần thưởng của những chiến binh đã chiến đấu tại Tế đàn Eldarah, Bên trong có nhiều vật phẩm quý hiếm. Cần 25 điểm hoạt động để mở rương', 'icon\\733', '0', 0, 'ui/205'),
(318, 19, 0, 'Tinh linh Rồng Zyren', 'Zyren và Vaelor là cặp song sinh thuộc dòng tộc Tinh linh Rồng mang sức mạnh tiệm cận với các Tinh linh, Thực thể đại diện cho Mặt trăng và Mặt trời, cận vệ cổ xưa nhất của bầu trời Eldarah', 'icon\\767', '0', 0, 'ui/204'),
(319, 19, 0, 'Tinh linh Rồng Vaelor', 'Zyren và Vaelor là cặp song sinh thuộc dòng tộc Tinh linh Rồng mang sức mạnh tiệm cận với các Tinh linh, Thực thể đại diện cho Mặt trăng và Mặt trời, cận vệ cổ xưa nhất của bầu trời Eldarah', 'icon\\766', '0', 0, 'ui/204'),
(320, 36, 0, 'Mặt nạ Thiên tích', 'Mặt nạ Thiên tích', 'icon\\760', '0', 0, 'ui/203'),
(321, 36, 0, 'Mặt nạ Bầu trời', 'Mặt nạ Bầu trời', 'icon\\761', '0', 0, 'ui/204'),
(322, 37, 0, 'Zarvok', 'Zarvok là loài chiến thú cực kỳ hung dữ khi cảm nhận được linh lực, được các Cận Vệ Thiên Tích sử dụng để tuần tra bầu trời. Zarvok sở hữu bộ vuốt sắc như móc thép đủ sức nghiền nát giáp đá của các chiến binh Eldarah.', 'icon\\765', '0', 0, 'ui/203'),
(323, 18, 0, 'Rương Ngoại trang', 'Vật phẩm khởi đầu dành cho những tân binh của Làng ánh sáng. Bên trong chứa 1 Ngoại trang ngẫu nhiên có HSD 3 ngày', 'icon\\754', '0', 0, 'ui/203'),
(324, 36, 0, 'Mặt nạ Cao nguyên', 'Mặt nạ Cao nguyên', 'icon\\780', '0', 0, 'ui/204'),
(325, 36, 0, 'Mặt nạ Đầm lầy', 'Mặt nạ Đầm lầy', 'icon\\781', '0', 0, 'ui/204'),
(326, 20, 0, 'Danh hiệu Ve chai', 'Danh hiệu Ve chai', 'icon\\784', '0', 0, 'ui/204'),
(327, 36, 0, 'Mặt nạ Linh hồn', 'Mặt nạ Linh hồn', 'icon\\782', '0', 0, 'ui/204'),
(328, 37, 0, 'Cổ mầm Linh mộc', 'Khi rễ Linh Mộc lan xuống lòng đất và tích tụ linh khí qua hàng trăm năm, chúng kết tinh thành những sinh linh mang hình hài nửa thú, nửa cây. Cổ mầm Linh mộc là một trong những thực thể như vậy.', 'icon\\786', '0', 0, 'ui/204'),
(329, 20, 0, 'Danh hiệu Thợ rèn', 'Danh hiệu Thợ rèn', 'icon\\783', '0', 0, 'ui/204'),
(330, 37, 0, 'Hỏa mầm Linh mộc', 'Khi rễ Linh Mộc lan xuống lòng đất và tích tụ linh khí qua hàng trăm năm, chúng kết tinh thành những sinh linh mang hình hài nửa thú, nửa cây. Hỏa mầm Linh mộc là một trong những thực thể như vậy.', 'icon\\785', '0', 0, 'ui/204'),
(331, 99, 0, 'Bùa chuyển hóa', 'Lá bùa mang sức mạnh biến đổi đặc biệt, cho phép chuyển hóa toàn bộ cấp cường hóa của trang bị sang một trang bị khác mà vẫn bảo toàn những giá trị quan trọng', 'icon\\790', '0', 0, 'ui/203'),
(332, 37, 0, 'Ngọc thố', 'Linh thú Mặt trăng thường xuất hiện vào những đêm trăng tròn, Ngọc thố là người bạn nhỏ đồng hành bên Nguyệt Linh Thần mỗi dịp Trung Thu', 'icon\\936', '0', 0, 'ui/204'),
(333, 37, 0, 'Huyết nguyệt Lang', 'Sinh ra dưới ánh Trăng máu, Huyết nguyệt Lang mang trong mình một phần tà lực của Dạ Xoa. Mỗi khi trăng tròn, tiếng tru của chúng sẽ vang lên trong màn đêm, báo hiệu Huyết Nguyệt sắp bao phủ bầu trời', 'icon\\935', '0', 0, 'ui/204'),
(337, 19, 0, 'Nguyệt linh thần', 'Tinh linh thuần khiết được sinh ra từ ánh trăng non cùng nguồn linh lực huyền bí, được xem là hiện thân của Mặt trăng và sự bình yên trong màn đêm. Vào đêm Trung Thu, Nguyệt linh thần sẽ xuất hiện để thanh tẩy và xoa dịu những linh hồn cuồng loạn bảo vệ sự cân bằng của Eldarah', 'icon\\929', '0', 0, 'ui/205'),
(338, 19, 0, 'Cổ thần Dạ xoa', 'Dạ xoa là một Cổ thần hung bạo từng gieo rắc tai họa trong thời đại xa xưa. Hắn có khả năng hấp thụ sức mạnh của mặt trăng. Vào đêm Trung Thu, Cổ thần Dạ Xoa lại một lần nữa thức tỉnh mang theo sức mạnh Trăng máu bao phủ khắp lục địa Eldarah', 'icon\\933', '0', 0, 'ui/205'),
(340, 36, 0, 'Mặt nạ Huyết nguyệt', 'Mặt nạ Huyết nguyệt', 'icon\\931', '0', 0, 'ui/204'),
(341, 36, 0, 'Mặt nạ Quỷ nguyệt', 'Mặt nạ Quỷ nguyệt', 'icon\\930', '0', 0, 'ui/205'),
(342, 36, 0, 'Mặt nạ Ngọc thố', 'Mặt nạ Ngọc thố', 'icon\\932', '0', 0, 'ui/203'),
(343, 99, 0, 'Bột mì', 'Vật phẩm sự kiện. Nguyên liệu làm bánh trung thu', 'icon\\940', '0', 0, 'ui/201'),
(344, 99, 0, 'Bột nếp', 'Vật phẩm sự kiện. Nguyên liệu làm bánh trung thu', 'icon\\941', '0', 0, 'ui/201'),
(345, 99, 0, 'Đường', 'Vật phẩm sự kiện. Nguyên liệu làm bánh trung thu', 'icon\\942', '0', 0, 'ui/201'),
(346, 99, 0, 'Sữa tươi', 'Vật phẩm sự kiện. Nguyên liệu làm bánh trung thu', 'icon\\946', '0', 0, 'ui/201'),
(347, 99, 0, 'Trứng muối', 'Vật phẩm sự kiện. Nguyên liệu làm bánh trung thu', 'icon\\943', '0', 0, 'ui/203'),
(349, 18, 0, 'Bánh dẻo', 'Vật phẩm sự kiện. Bên trong có chứa nhiều vật phẩm quý hiếm từ sự kiện trung thu 2026', 'icon\\945', '0', 0, 'ui/205'),
(350, 18, 0, 'Bánh nướng', 'Vật phẩm sự kiện. Bên trong có chứa nhiều vật phẩm quý hiếm từ sự kiện trung thu 2026', 'icon\\944', '0', 0, 'ui/205'),
(351, 99, 0, 'Cà rốt', 'Vật phẩm sự kiện. Là món ăn yêu thích của Ngọc Thố, chỉ cần mang theo vài củ là có thể khiến chúng vui vẻ chạy đến bên bạn', 'icon\\939', '0', 0, 'ui/203'),
(352, 48, 0, 'Đèn lồng Trung thu', 'Chiếc đèn lồng nhỏ được thắp sáng trong đêm Trung Thu. Ánh sáng ấm áp đem lại bình an và dẫn lối cho những người lữ hành dưới ánh trăng.', 'icon\\968', '0', 0, 'ui/204'),
(353, 48, 0, 'Giỏ táo', 'Giỏ đựng Táo được đan từ dây leo chắc chắn, được dùng để tích trữ táo trong những chuyến hành trình giúp bảo quản những quả Táo trong thời gian dài', 'icon\\948', '0', 0, 'ui/204'),
(354, 18, 0, 'Đèn hoa đăng', 'Ngọn đèn nhỏ mang theo những lời cầu nguyện trong đêm Trung Thu. Khi được thả trôi theo dòng nước nó sẽ mang lại một phần quà ngẫu nhiên. Cần 25 điểm hoạt động để sử dụng', 'icon\\950', '0', 0, 'ui/205'),
(355, 49, 0, 'Ống tre kinh nghiệm', 'Chứa đựng nguồn năng lượng bí ẩn. Khi mở ra, nguồn linh lực bên trong sẽ hòa vào cơ thể và nhận 5.000 Kinh nghiệm, tăng 100% với mỗi cấp độ người chơi.', 'icon\\970', '0', 15, 'ui/204'),
(356, 20, 0, 'Danh hiệu Khởi nguyên', 'Danh hiệu Khởi nguyên', 'icon\\981', '0', 0, 'ui/203'),
(357, 50, 0, 'Túi tân thủ', 'Vật phẩm khởi đầu dành cho những tân binh của Làng ánh sáng. Bên trong chứa 1 bộ trang bị khởi đầu', 'icon\\971', '0', 0, 'ui/203'),
(358, 99, 0, 'Bùa thanh tẩy', 'Lá bùa cổ được Tư tế tạo ra để thanh tẩy Sát khí và gột oán niệm bám trên người các chiến binh của bộ lạc, Sử dụng để xóa toàn bộ điểm Sát khí', 'icon\\972', '0', 0, 'ui/203'),
(360, 99, 0, 'Huy hiệu Tinh Linh (1 Ngày)', 'Chiếc huy hiệu khắc biểu tượng ngôi sao của bộ lạc có thể mở ra danh sách tiện ích và có thể sử dụng tính năng Luyện tập Offline trong vòng 1 ngày (Có thể cộng dồn)', 'icon\\446', '0', 0, 'ui/205'),
(361, 18, 0, 'Thỏi vàng', 'Một khối kim loại vàng quý hiếm được tinh luyện và đúc thành thỏi. Sử dụng sẽ nhận được 1.000.000 vàng', 'icon\\683', '0', 0, 'ui/205'),
(362, 48, 0, 'Chày xương thú', 'Chiếc chày thô sơ được chế từ xương Tê giác cứng chắc với những chiếc gai nhọn. Vũ khí đáng sợ của những thổ dân Thảo nguyên', 'icon\\974', '0', 0, 'ui/203'),
(363, 48, 0, 'Chày đùi gà', 'Đùi của Đà điểu Thảo nguyên khổng lồ được chế thành một chiếc chày chiến đấu. Trông có vẻ ngon mắt', 'icon\\973', '0', 0, 'ui/203'),
(364, 36, 0, 'Mặt nạ Sayari', 'Mặt nạ Sayari', 'icon\\975', '0', 0, 'ui/204'),
(365, 36, 0, 'Mặt nạ Avenna', 'Mặt nạ Avenna', 'icon\\976', '0', 0, 'ui/204'),
(366, 36, 0, 'Mặt nạ Velmora', 'Mặt nạ Velmora', 'icon\\977', '0', 0, 'ui/204'),
(367, 36, 0, 'Mặt nạ Darguun', 'Mặt nạ Darguun', 'icon\\978', '0', 0, 'ui/204'),
(368, 36, 0, 'Mặt nạ Frearh', 'Mặt nạ Frearh', 'icon\\979', '0', 0, 'ui/204'),
(369, 36, 0, 'Mặt nạ Sấm sét', 'Mặt nạ Sấm sét', 'icon\\980', '0', 0, 'ui/204'),
(370, 99, 0, 'Mảnh Totem', 'Mảnh vỡ của một vật tổ cổ xưa, vẫn còn lưu giữ chút linh lực huyền bí. Thu thập 10 mảnh vỡ để ghép thành 1 Vật tổ Savah', 'icon\\980', '0', 0, 'ui/203'),
(371, 99, 0, 'Vật tổ Savah', 'Linh vật cổ xửa huyên bí của người dân Savah, thu thập qua các trận chiến Bộ lạc khốc liệt dùng để trao đổi với người dân Savah đổi lấy nhiều vật phẩm quý hiểm', 'icon\\980', '0', 0, 'ui/204'),
(372, 99, 0, 'Vật tổ Savah', 'Linh vật cổ xửa huyên bí của người dân Savah, thu thập qua các trận chiến Bộ lạc khốc liệt dùng để trao đổi với người dân Savah đổi lấy nhiều vật phẩm quý hiểm', 'icon\\980', '0', 0, 'ui/200'),
(373, 19, 0, 'Tinh linh Thảo nguyên', 'Tinh linh cổ xưa mang trong mình sức mạnh của thiên nhiên hoang dã, được sinh ra từ linh khí của vùng thảo nguyên Savanna, vị thần ngự trị vùng đất tổ thiêng liêng và phán xử các bộ lạc Savah', 'icon\\980', '0', 0, 'ui/205'),
(374, 19, 0, 'Hoàng tử M\'Baku', 'M\'Baku là hoàng tử của bộ lạc Karu, dù mang thân phận người kế vị, anh vẫn thường sát cánh cùng các chiến binh ngày đêm chiến đấu bảo vệ bộ lạc kể từ khi những cuộc Chiến tranh Vật tổ nổ ra', 'icon\\980', '0', 0, 'ui/204'),
(375, 19, 0, 'K\'Zuri', 'K\'Zuri là thợ săn của bộ lạc Zama. Thế nhưng, cô lại có mối quan hệ thân thiết với M\'Baku, vị hoàng tử của bộ lạc đối địch. Giữa những ân oán kéo dài qua nhiều thế hệ, dường như một tình cảm đặc biệt đang âm thầm nảy nở giữa hai người.', 'icon\\980', '0', 0, 'ui/204'),
(376, 36, 0, 'Mặt nạ Thảo nguyên', 'Mặt nạ Thảo nguyên', 'icon\\983', '0', 0, 'ui/204'),
(377, 36, 0, 'Mặt nạ Diều hâu', 'Mặt nạ Diều hâu', 'icon\\984', '0', 0, 'ui/204'),
(378, 36, 0, 'Mặt nạ Tư tế', 'Mặt nạ Tư tế', 'icon\\982', '0', 0, 'ui/203'),
(379, 18, 0, 'Túi Siêu linh hồn Tấn công', 'Ẩn chứa linh lực công phá tinh túy của thảo nguyên Savah. Mở ra ngẫu nhiên một Bùa Linh Hồn dòng chỉ số Tấn công vượt trội', 'icon\\980', '0', 0, 'ui/204'),
(380, 18, 0, 'Túi Siêu linh hồn Phòng thủ', 'Ẩn chứa linh lực phòng hộ tinh túy của thảo nguyên Savah. Mở ra ngẫu nhiên một Bùa Linh Hồn dòng chỉ số Phòng Thủ vượt trội', 'icon\\980', '0', 0, 'ui/204'),
(381, 18, 0, 'Túi Siêu linh hồn Đa dụng', 'Ẩn chứa linh lực đa dạng tinh túy của thảo nguyên Savah. Mở ra ngẫu nhiên một Bùa Linh Hồn dòng chỉ số Đa dụng vượt trội', 'icon\\980', '0', 0, 'ui/204'),
(382, 37, 0, 'Đà điểu Tumba', 'Sinh sống trên những đồng cỏ rộng lớn của Savah, nổi tiếng với đôi chân khỏe và tốc độ phi thường, loài Tumba được các bộ lạc thuần dưỡng và đồng hành cùng những chiến binh trong các chuyến săn và hành trình băng qua thảo nguyên', 'icon\\765', '0', 0, 'ui/204');
