INSERT INTO `skill_template` (`id`, `name`, `target_type`, `class_id`, `mana_cost_type`, `description`, `icon_paths`) VALUES
(1, '1. Đánh Thường', 1, 1, 1, 'Giải phóng sức mạnh thể chất, tung ra những đòn tấn công cơ bản nhưng đầy uy lực', '[\"icon/464\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(2, '2. Đánh Thường', 1, 2, 1, 'Giải phóng sức mạnh linh vũ, tung ra những đòn tấn công cơ bản nhưng đầy uy lực', '[\"icon/411\",\"icon/184\",\"icon/190\",\"icon/196\",\"icon/202\",\"icon/208\"]'),
(3, '3. Xuyên Phá Trảm', 1, 2, 1, 'Dồn sức mạnh vào lưỡi rìu rồi vung rìu bổ mạnh theo đường thẳng về phía trước xuyên qua lớp phòng thủ của mục tiêu', '[\"icon/412\",\"icon/185\",\"icon/191\",\"icon/197\",\"icon/203\",\"icon/209\"]'),
(4, '4. Trụ Tái Tạo', 2, 2, 2, 'Thu mình về thế phòng ngự trong 5 giây, tạo ra làn sóng năng lượng hồi phục lại một phần HP đồng thời giảm sát thương nhận vào trong thời gian thi triển', '[\"icon/413\",\"icon/186\",\"icon/192\",\"icon/198\",\"icon/204\",\"icon/210\"]'),
(5, '5. Cuồng Phong Trảm', 2, 2, 1, 'Vung rìu xoay tròn với lực gió cuộn mạnh tạo thành cơn lốc xoáy xung quanh cơ thể liên tục gây sát thương lên các mục tiêu trong tầm ảnh hưởng', '[\"icon/414\",\"icon/187\",\"icon/193\",\"icon/199\",\"icon/205\",\"icon/211\"]'),
(6, '6. Viễn Tâm Trảm', 1, 2, 1, 'Dồn sức vào cánh tay và ném rìu về phía trước với uy lực cực mạnh nhắm thẳng vào mục tiêu ở khoảng cách xa gây một lượng sát thương lớn và khiến mục tiêu bị chảy máu trong thoáng chốc', '[\"icon/415\",\"icon/188\",\"icon/194\",\"icon/200\",\"icon/206\",\"icon/212\"]'),
(7, '7. Thịnh Nộ Trảm', 1, 2, 2, 'Hạ thấp trọng tâm và dồn toàn bộ sức mạnh vào lưỡi rìu đồng thời phát ra những tia năng lượng nguyên tố mãnh liệt, sau vài giây nhảy lên và bổ mạnh vào mục tiêu gây lượng sát thương cực lớn', '[\"icon/416\",\"icon/189\",\"icon/195\",\"icon/201\",\"icon/207\",\"icon/213\"]'),
(8, '8. Đánh Thường', 1, 3, 1, 'Giải phóng sức mạnh linh vũ, tung ra những đòn tấn công cơ bản nhưng đầy uy lực', '[\"icon/423\",\"icon/321\",\"icon/327\",\"icon/333\",\"icon/339\",\"icon/345\"]'),
(9, '9. Bão Vũ Tiễn', 1, 3, 1, 'Liên tục bắn ra 5 mũi tên nhắm vào một mục tiêu duy nhất mang theo sát ý mạnh mẽ và độ chính xác cao', '[\"icon/424\",\"icon/322\",\"icon/328\",\"icon/334\",\"icon/340\",\"icon/346\"]'),
(10, '10. Lá Chắn Tiễn', 2, 3, 2, 'Triệu hồi một kết giới tâm linh bao quanh bản thân giúp giảm sát thương nhận vào và phản lại một phần sát thương lên kẻ tấn công', '[\"icon/425\",\"icon/323\",\"icon/329\",\"icon/335\",\"icon/341\",\"icon/347\"]'),
(11, '11. Tán Diệt Tiễn', 1, 3, 1, 'Bắn một mũi tên lớn vào mục tiêu chính, gây sát thương trực diện. Cùng lúc đó, 10 mũi tên nhỏ bắn ra xung quanh vào ngẫu nhiên các mục tiêu gần đó, mỗi mũi tên nhỏ gây 10% sát thương', '[\"icon/426\",\"icon/324\",\"icon/330\",\"icon/336\",\"icon/342\",\"icon/348\"]'),
(12, '12. Băng Diệt Tiễn', 1, 3, 1, 'Kéo căng dây cung và phóng ra một mũi tên kết tinh băng giá, xuyên thẳng vào mục tiêu và gây sát thương. Sức lạnh lan theo vết thương có thể đóng băng mục tiêu trong chốc lát', '[\"icon/427\",\"icon/325\",\"icon/331\",\"icon/337\",\"icon/343\",\"icon/349\"]'),
(13, '13. Tuyệt Diệt Tiễn', 1, 3, 2, 'Dương cung và giữ thế ngắm trong vài giây, tập trung toàn bộ sức mạnh bắn ra một mũi tên khổng lồ, mũi tên xé gió lao thẳng vào kẻ địch, với sức xuyên phá cực lớn và gây lượng sát thương áp đảo', '[\"icon/428\",\"icon/326\",\"icon/332\",\"icon/338\",\"icon/344\",\"icon/350\"]'),
(14, '14. Đánh Thường', 1, 4, 1, 'Giải phóng sức mạnh linh vũ, tung ra những đòn tấn công cơ bản nhưng đầy uy lực', '[\"icon/435\",\"icon/381\",\"icon/387\",\"icon/393\",\"icon/399\",\"icon/405\"]'),
(15, '15. Tam Thạch Nỗ', 1, 4, 1, 'Bắn liền 3 viên đá nhỏ về phía kẻ địch mang theo năng lượng hỗn loạn khiến mục tiêu bị suy yếu trong thoáng chốc', '[\"icon/436\",\"icon/382\",\"icon/388\",\"icon/394\",\"icon/400\",\"icon/406\"]'),
(16, '16. Phá Tốc Nỗ', 2, 4, 1, 'Siết chặt ná thun, tạo nguồn năng lượng đặc biệt khiến cơ thể trở nên linh hoạt trong một khoảng thời gian ngắn giúp gia tăng tốc độ tấn công và tốc độ di chuyển', '[\"icon/437\",\"icon/383\",\"icon/389\",\"icon/395\",\"icon/401\",\"icon/407\"]'),
(17, '17. Xung Kích Nỗ', 1, 4, 1, 'Bắn một viên đá nén lực vào mục tiêu khiến nó vỡ vụn ngay khi trúng đích. Mảnh vỡ lan ra tạo thành sóng xung kích, gây 20% sát thương lên 5 mục tiêu đứng gần đó', '[\"icon/438\",\"icon/384\",\"icon/390\",\"icon/396\",\"icon/402\",\"icon/408\"]'),
(18, '18. Lôi Kích Nỗ', 1, 4, 1, 'Bắn một viên đá thu lôi vào mục tiêu, gây sát thương trực diện. Khi viên đá chạm vào kẻ địch, năng lượng tích tụ bên trong có thể kích hoạt tia sét đánh thẳng xuống, khiến mục tiêu bị giật trong thoáng chốc', '[\"icon/439\",\"icon/385\",\"icon/391\",\"icon/397\",\"icon/403\",\"icon/409\"]'),
(19, '19. Thần Phong Nỗ', 1, 4, 2, 'Kéo căng dây thun đến mức tối đa tạo nên một làn gió năng lượng xoáy tụ quanh viên đá trong vài giây, sau đó bắn ra một viên đá khổng lao lao vút theo không khí và gây sát thương cực lớn lên mục tiêu trúng đòn', '[\"icon/440\",\"icon/386\",\"icon/392\",\"icon/398\",\"icon/404\",\"icon/410\"]'),
(20, '20. Đánh Thường', 1, 5, 1, 'Giải phóng sức mạnh linh vũ, tung ra những đòn tấn công cơ bản nhưng đầy uy lực', '[\"icon/417\",\"icon/291\",\"icon/297\",\"icon/303\",\"icon/309\",\"icon/315\"]'),
(21, '21. Vũ Mâu Kích', 1, 5, 1, 'Vận sức tung ra 5 cú đâm giáo liên tiếp vào mục tiêu, với mỗi đòn đều nhanh gọn và chính xác nhắm vào điểm yếu chí mạng', '[\"icon/418\",\"icon/292\",\"icon/298\",\"icon/304\",\"icon/310\",\"icon/316\"]'),
(22, '22. Xuyên Tâm Kích', 1, 5, 1, 'Đâm mũi giáo về phía trước theo một đường thẳng lao đi xuyên thủng mọi thứ trên đường đi đồng thời hồi lại HP bằng một phần sát thương đã gây ra', '[\"icon/419\",\"icon/293\",\"icon/299\",\"icon/305\",\"icon/311\",\"icon/317\"]'),
(23, '23. Trấn Địa Kích', 1, 5, 1, 'Bật nhảy lên không, dồn lực vào mũi giáo rồi giáng mạnh một đòn xuống mặt đất tạo ra chấn động và gây lượng sát thương lớn lên mục tiêu trúng đòn', '[\"icon/420\",\"icon/294\",\"icon/300\",\"icon/306\",\"icon/312\",\"icon/318\"]'),
(24, '24. Phá Địa Kích', 1, 5, 1, 'Đâm mạnh xuống đất, tạo một luồng chấn động theo hướng mục tiêu. Tại vị trí kẻ địch, mặt đất vỡ ra và nhiều mũi giáo nhỏ trồi lên từ dưới đất gây sát thương và có thể gây choáng mục tiêu', '[\"icon/421\",\"icon/295\",\"icon/301\",\"icon/307\",\"icon/313\",\"icon/319\"]'),
(25, '25. Mâu Thần Kích', 1, 5, 2, 'Gồng mình vào thế phóng lao, tập trung toàn bộ sức lực vào mũi giáo trong vài giây sau đó ném thẳng cây giáo về phía mục tiêu mang theo sức nặng khủng khiếp, xuyên phá đối thủ và gây lượng sát thương cực lớn', '[\"icon/422\",\"icon/296\",\"icon/302\",\"icon/308\",\"icon/314\",\"icon/320\"]'),
(26, '26. Đánh Thường', 1, 6, 1, 'Giải phóng sức mạnh linh vũ, tung ra những đòn tấn công cơ bản nhưng đầy uy lực', '[\"icon/429\",\"icon/351\",\"icon/357\",\"icon/363\",\"icon/369\",\"icon/375\"]'),
(27, '27. Song Ảnh Phách', 1, 6, 1, 'Quất roi liên tiếp 2 lần vào mục tiêu, tiếng roi rít xé gió mang theo lực xung kích lớn và có thể khiến mục tiêu bị choáng', '[\"icon/430\",\"icon/352\",\"icon/358\",\"icon/364\",\"icon/370\",\"icon/376\"]'),
(28, '28. Ảo Ảnh Phách', 2, 6, 1, 'Lướt nhanh về phía trước và trở nên vô hình trong vài giây đồng thời để lại ảnh ảo có thể tấn công các mục tiêu xung quanh trong thời gian hiệu lực', '[\"icon/431\",\"icon/353\",\"icon/359\",\"icon/365\",\"icon/371\",\"icon/377\"]'),
(29, '29. Tàn Ảnh Phách', 1, 6, 1, 'Vung roi lên cao, dồn lực vào mũi roi rồi quất mạnh xuống mặt đất, tạo ra một cú đánh dứt khoát và gây sát thương lên mục tiêu trúng đòn', '[\"icon/432\",\"icon/354\",\"icon/360\",\"icon/366\",\"icon/372\",\"icon/378\"]'),
(30, '30. Mộc Ảnh Phách', 1, 6, 1, 'Triệu hồi đám dây leo mọc lên từ dưới đất nhanh chóng cuốn chặt lấy mục tiêu trong thoáng chốc, đồng thời quất mạnh roi tấn công vào kẻ địch, gây sát thương lên mục tiêu trúng đòn', '[\"icon/433\",\"icon/355\",\"icon/361\",\"icon/367\",\"icon/373\",\"icon/379\"]'),
(31, '31. Kình Lực Phách', 1, 6, 2, 'Vung roi quay nhiều vòng liên tiếp trong vài gây tạo lực xoáy mạnh dần khiến không khí rung lên dồn quán tính và vụt mạnh xuống mặt đất, tạo ra kình lực chấn động gây sát thương cực lớn lên mục tiêu trúng đòn', '[\"icon/434\",\"icon/356\",\"icon/362\",\"icon/368\",\"icon/374\",\"icon/380\"]'),
(32, '32. Kỹ năng 1', 1, 7, 1, 'Đánh Thường', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(33, '33. Kỹ năng 2', 2, 7, 1, 'Đánh Thường', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(34, '34. Kỹ năng 3', 2, 7, 1, 'Đánh Thường', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(35, '35. Kỹ năng 4', 2, 7, 1, 'Triệu hồi rễ cây trói 3 mục tiêu ngẫu nhiên và hút sinh lực của chúng trong 15 giây', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(36, '36. Kỹ năng 5', 2, 7, 1, 'Giảm 50% sức chiến đấu của 3 mục tiêu ngẫu nhiên và khiến chúng bị suy yếu trong 15 giây ', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(37, '37. Kỹ năng 6', 2, 7, 1, 'Tạo 1 lớp khiên nước bảo vệ bản thân giảm 75% sát thương nhận vào trong 15 giây', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(38, '38. Kỹ năng 7', 2, 7, 1, 'Tấn công 3 mục tiêu ngẫu nhiên bằng trấn động địa chấn gây sát thương và làm choáng mục tiêu trong 15 giây', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(39, '39. Kỹ năng 8', 2, 7, 1, 'Tạo ra môi trường lạnh buốt đóng băng tất cả các mục tiêu xung quanh trong 15 giây', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(40, '40. Kỹ năng 9', 2, 7, 1, 'Phóng ra 50 lông vũ vào các mục tiêu ngẫu nhiên mỗi lông vũ gây 500% sát thương cơ bản', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(41, '41. Kỹ năng 10', 1, 7, 1, 'Ném cây tầm sét vào mục tiêu gây một lượng sát thương cực lớn bằng 1000% sát thương cơ bản', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]'),
(42, '42. Loạn Ảnh Phách', 2, 6, 1, 'Quất loạn roi liên tiếp quanh bản thân, tiếng roi rít xé gió mang theo lực xung kích lớn gây sát thương 5 lần lên các mục tiêu xung quanh', '[\"icon/430\",\"icon/352\",\"icon/358\",\"icon/364\",\"icon/370\",\"icon/376\"]'),
(43, '43. Kỹ năng 11', 2, 7, 1, 'Hút 20% Sinh lực của 5 mục tiêu ngẫu nhiên và hồi lại cho bản thân lượng HP tương đương', '[\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\",\"icon/183\"]');
