INSERT INTO `talent` (`id`, `name`, `icon`, `description`, `point_cost`) VALUES
(1, 'Sinh lực', 'icon\\233', 'Sinh lực và sức bền của nhân vật. HP càng cao, khả năng chống chịu sát thương càng tốt. Khi HP giảm về 0, nhân vật sẽ kiệt sức và không thể hành động.\r\n- - - - - - - - - - - - - - - - - - - - - - - - - - - -\r\n+10 HP', 1),
(2, 'Trí lực', 'icon\\234', 'Năng lượng của nhân vật dùng để thi triển kỹ năng và chiêu thức. Mỗi kỹ năng tiêu hao một lượng MP nhất định. Khi MP không đủ, nhân vật không thể sử dụng kỹ năng.\r\n- - - - - - - - - - - - - - - - - - - - - - - - - - - -\r\n+10 MP', 1),
(3, 'Nhanh nhẹn', 'icon\\236', 'Tăng cường khả năng phản xạ. Nhanh nhẹn càng cao, khả năng né tránh đòn tấn công càng tốt, giúp nhân vật linh hoạt thoát khỏi nguy hiểm.\r\n- - - - - - - - - - - - - - - - - - - - - - - - - - - -\r\n+1 Né tránh', 2),
(4, 'Tập trung', 'icon\\237', 'Tăng cường sự ổn định và chính xác trong chiến đấu. Chỉ số tập trung càng cao, đòn tấn công càng dễ trúng mục tiêu, giảm thiểu khả năng đánh trượt.\r\n- - - - - - - - - - - - - - - - - - - - - - - - - - - -\r\n+1 Chính xác', 2),
(5, 'Bạo kích', 'icon\\238', 'Tăng cường tỷ lệ tung ra đòn chí mạng trong trận đấu. Khi bạo kích cao, mỗi cú đánh có thể bộc phát sức mạnh gấp đôi, gây sát thương vượt trội bất ngờ.\r\n- - - - - - - - - - - - - - - - - - - - - - - - - - - -\r\n+1 Chí mạng', 2),
(6, 'Sức mạnh', 'icon\\235', 'Tăng khả năng tấn công của nhân vật. Sức mạnh càng cao, mỗi đòn đánh và chưởng lực tung ra càng gây sát thương lớn, dễ dàng áp đảo đối thủ.\r\n- - - - - - - - - - - - - - - - - - - - - - - - - - - -\r\n+1 Tấn công', 3);
